page-2	/expertises/	Expertises	published	cms	default	[{"id": "b-gpayqfaz", "data": {"image": "/themes/ultra-s/images/pexen/ingenieur-pexen-sur-site-ingenierie-et-performance-energetique.webp", "intro": "PEXEN accompagne les sites industriels, tertiaires et résidentiels collectifs à chaque étape d'un projet de performance énergétique : l'étude, les travaux, l'engagement de résultat et le financement. Une seule équipe, du premier relevé au bilan d'économies.", "title": "Nos expertises, de l'étude au suivi", "buttons": [{"id": "btn-rk15u28t", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-2zf1z4of", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Expertises", "metrics": [{"id": "m-ccf0485o", "label": "de l'étude au financement", "value": "4 expertises"}, {"id": "m-j6io3x64", "label": "du premier relevé au bilan d'économies", "value": "1 équipe"}, {"id": "m-1ycz7n23", "label": "contrôle par un organisme accrédité", "value": "COFRAC"}], "imageAlt": "Nos expertises, de l'étude au suivi", "breadcrumb": true, "heroVariant": "expertise"}, "type": "pageHeader", "style": {"background": "surface", "paddingBottom": "md"}}, {"id": "b-9dw1raxv", "data": {"items": [{"id": "c-wtknurf1", "link": "/expertises/bureau-etudes-fluides/", "tags": [], "text": "Audit, relevés, dimensionnement et solutions techniques.", "image": "/themes/ultra-s/images/pexen/audit-batiment.webp", "title": "Études et ingénierie", "linkLabel": "Découvrir l'expertise"}, {"id": "c-q3ghgmy7", "link": "/expertises/assistance-maitrise-ouvrage/", "tags": [], "text": "Planification, suivi de chantier et mise en service.", "image": "/themes/ultra-s/images/pexen/pexen-partenaire-installateur-livraison-d-equipements-sur-chantier.webp", "title": "Accompagnement travaux et AMO", "linkLabel": "Découvrir l'expertise"}, {"id": "c-0g5ovtwq", "link": "/expertises/contrat-performance-energetique/", "tags": [], "text": "Objectifs, mesure et suivi des consommations.", "image": "/themes/ultra-s/images/pexen/contrat-de-performance-energetique-sur-une-centrale-de-froid-commercial.webp", "title": "Contrat de performance énergétique", "linkLabel": "Découvrir l'expertise"}, {"id": "c-0mj5vv81", "link": "/expertises/financement-cee-reglementation/", "tags": [], "text": "Décret tertiaire, décret BACS et aides financières.", "image": "/themes/ultra-s/images/pexen/cee-tertiaire.webp", "title": "Réglementation et financement", "linkLabel": "Découvrir l'expertise"}], "style": "hoverDark", "title": "Quatre expertises, une seule équipe", "columns": 2, "eyebrow": "Expertises", "headerLink": "", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "surface", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-if0fb30q", "data": {"html": "<p>Prévisite et audit, dimensionnement et ingénierie technico-financière, installation et mise en service, puis contrôle COFRAC et suivi des performances : quatre étapes, un livrable daté à chaque étape.</p>", "image": "/themes/ultra-s/images/pexen/performance-energetique.webp", "ratio": "landscape", "title": "De l'audit à la mesure des économies", "bullets": [], "buttons": [{"id": "btn-a15705af", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "eyebrow": "Méthode", "autoplay": false, "imageAlt": "Méthode PEXEN", "highlight": "", "mediaType": "image", "mediaStyle": "framed", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-5s1u44t8", "data": {"items": [{"id": "f-ezq6ve1y", "answer": "<p>Partout en France métropolitaine, depuis notre siège d'Aubervilliers (Seine-Saint-Denis).</p>", "question": "Où intervenez-vous ?"}, {"id": "f-9hf8lny6", "answer": "<p>Oui. PEXEN dimensionne, installe et met en service, avec ses équipes et des partenaires qualifiés, puis suit les consommations.</p>", "question": "Réalisez-vous les travaux vous-mêmes ?"}], "title": "Questions fréquentes", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-w4qg1vpe", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-2qd9bzjr", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-xcrtwhhc", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "expertises", "noindex": true, "nofollow": false, "seoTitle": "Expertise énergétique : étude, travaux, CPE, financement | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "expertise énergétique", "metaDescription": "Les expertises PEXEN : bureau d'études fluides, accompagnement travaux, contrat de performance énergétique, réglementation et financement CEE. Une seule équipe."}	3	2026-10-12 09:02:46.153+02	\N	2026-10-12 09:02:46.153+02	2026-10-30 08:47:32.779+01	\N
p-nwlua9se	/cookies/	Cookies	published	cms	legal	[{"id": "b-xse5ntrl", "data": {"image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "intro": "", "title": "Cookies", "buttons": [], "eyebrow": "PEXEN", "breadcrumb": true, "parentLink": "", "parentLabel": "", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-u7f9n4zp", "data": {"html": "<p><em>Dernière mise à jour : 22 octobre 2026</em></p>\\n<p>Cette page détaille l’utilisation des cookies sur pexen.fr. Pour l’ensemble du traitement des données personnelles, consultez la <a href=\\"/politique-de-confidentialite/\\">politique de confidentialité</a>.</p>\\n<h2>Cookies</h2>\\n<p>Un cookie est un fichier déposé sur votre terminal lors de la consultation du Site. Le Site utilise :</p>\\n<div class=\\"table-responsive\\"><table class=\\"table\\"><thead><tr><th scope=\\"col\\">Catégorie</th><th scope=\\"col\\">Finalité</th><th scope=\\"col\\">Consentement</th><th scope=\\"col\\">Durée</th></tr></thead><tbody><tr><td>Cookies nécessaires</td><td>Fonctionnement et sécurité du Site, mémorisation de votre choix en matière de cookies</td><td>Non requis</td><td>6 mois au maximum</td></tr><tr><td>Mesure d&#x27;audience (Google Analytics 4 : _ga, _ga_GRR10GDECY)</td><td>Statistiques de fréquentation et amélioration des contenus</td><td>Requis</td><td>13 mois au maximum</td></tr></tbody></table></div>\\n<p>Lors de votre première visite, un bandeau vous permet d&#x27;accepter, de refuser ou de paramétrer les cookies soumis à consentement. Refuser est aussi simple qu&#x27;accepter. Aucun cookie de mesure d&#x27;audience n&#x27;est déposé avant votre choix. Vous pouvez modifier ce choix à tout moment grâce au lien « Gérer mes cookies » présent en bas de chaque page.</p>\\n<p>Vous pouvez également configurer votre navigateur pour bloquer les cookies. Les cookies nécessaires restant indispensables au fonctionnement du Site, leur blocage peut en limiter certaines fonctionnalités.</p>", "size": "normal"}, "type": "richText", "style": {"width": "narrow", "background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "cookies", "noindex": true, "nofollow": false, "seoTitle": "Cookies | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "", "metaDescription": "Les cookies utilisés sur pexen.fr : cookies nécessaires et mesure d’audience Google Analytics 4."}	7	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-10-21 14:32:24.684+02	\N
p-gbmq9fhb	/secteurs/efficacite-energetique-industrielle/	Industrie	published	cms	default	[{"id": "b-yff5ylk0", "data": {"image": "/themes/ultra-s/images/pexen/chaufferie-vapeur-d-un-site-industriel-efficacite-energetique-industrielle.webp", "intro": "Dans l’industrie, l’énergie est un coût de production et la continuité, une exigence. L’efficacité énergétique industrielle agit sur les utilités qui tournent en continu : production de froid, chaufferies, air comprimé, réseaux. PEXEN conduit les études et les travaux en coordination avec vos arrêts programmés, sans perturber les lignes.", "title": "Efficacité énergétique des sites industriels", "buttons": [{"id": "btn-m226cxkv", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-f245s1dd", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Secteurs", "metrics": [{"id": "m-8ff8ojww", "label": "seuil de l’audit énergétique obligatoire", "value": "2,75 GWh/an"}, {"id": "m-de157mn3", "label": "périodicité de l’audit réglementaire", "value": "4 ans"}, {"id": "m-z7bp7imn", "label": "audit industrie via notre bureau d’études partenaire", "value": "OPQIBI 1717"}], "imageAlt": "Chaufferie vapeur d’un site industriel, efficacité énergétique industrielle", "highlight": "Vos lignes ne s’arrêtent pas. Vos économies non plus.", "breadcrumb": true, "parentLink": "/secteurs/", "heroVariant": "sector", "parentLabel": "Secteurs"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "md"}}, {"id": "b-kdzq45x4", "data": {"intro": "", "items": [{"id": "c-f3agf7qi", "link": "", "tags": [], "text": "Froid process, vapeur et air comprimé tournent souvent 24 h sur 24 : chaque point de rendement gagné se répète jusqu’à 8 760 heures par an.", "title": "Le coût de l’énergie par unité produite", "imageAlt": "Le coût de l’énergie par unité produite", "linkLabel": ""}, {"id": "c-9877ykvq", "link": "", "tags": [], "text": "Les travaux se calent sur vos arrêts techniques et se réalisent en grande partie sur des installations en service.", "title": "La continuité de production", "imageAlt": "La continuité de production", "linkLabel": ""}, {"id": "c-rv3g1dzr", "link": "", "tags": [], "text": "À partir de 2,75 GWh consommés par an, sans système de management de l’énergie certifié, un audit est exigé tous les quatre ans.", "title": "L’audit énergétique obligatoire", "imageAlt": "L’audit énergétique obligatoire", "linkLabel": ""}], "style": "hoverDark", "title": "Vos enjeux industriels", "columns": 3, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-0t8mtt0i", "data": {"rows": [{"id": "r-sx35rcc4", "cells": ["Froid process", "Haute pression flottante", "IND-UT-116"]}, {"id": "r-8fyml739", "cells": ["Froid process", "Basse pression flottante", "IND-UT-115"]}, {"id": "r-ubwp3phe", "cells": ["Froid process", "Condensation haute efficacité", "IND-UT-113"]}, {"id": "r-ssq9g4ay", "cells": ["Moteurs, pompes, ventilateurs", "Variation électronique de vitesse", "IND-UT-102"]}, {"id": "r-670i895s", "cells": ["Chaleur perdue", "Récupération sur groupe froid", "IND-UT-117"]}, {"id": "r-5252lcl3", "cells": ["Chaleur perdue", "Récupération sur compresseur d’air", "IND-UT-103"]}, {"id": "r-tp4or0o9", "cells": ["Chaleur perdue", "PAC en rehausse de chaleur fatale", "IND-UT-137"]}, {"id": "r-gse5kbuv", "cells": ["Chaufferie", "Brûleur micro-modulant", "IND-UT-105"]}, {"id": "r-e8d2vxsp", "cells": ["Grande hauteur", "Déstratification d’air", "IND-BA-110"]}, {"id": "r-50065nh1", "cells": ["Réseaux", "Calorifugeage", "IND-UT-131"]}, {"id": "r-k98f3y1c", "cells": ["Réseaux", "Matelas isolants", "IND-UT-121"]}, {"id": "r-z7js2jo5", "cells": ["Pilotage", "Indicateurs de performance", "IND-UT-134"]}], "intro": "", "title": "Nos solutions d’efficacité énergétique industrielle", "columns": ["Poste", "Solution PEXEN", "Fiche CEE industrie"], "eyebrow": "", "searchable": false}, "type": "table", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-ry4a2p3z", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-lavyj5ff", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-ji4pa9rx", "data": {"html": "<h2>Une démarche adaptée aux contraintes industrielles</h2><p>Le relevé s'appuie sur vos données de comptage et sur des mesures ponctuelles : puissances, températures, temps de fonctionnement. L'étude classe les actions par temps de retour, CEE déduits. Les audits réglementaires sont conduits avec notre partenaire Leo Energy, qualifié OPQIBI 1717 pour l'industrie.</p><p><a href=\\"/notre-approche/\\">Notre approche</a></p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-n3wxjp6a", "data": {"cards": [{"id": "ck-qij67hn1", "icon": "fa-check", "title": "", "entries": [{"id": "e-i923du24", "title": "Froid process : régulation flottante, condensation haute efficacité, récupération de la chaleur rejetée."}, {"id": "e-zsgdiv51", "title": "Air comprimé : fuites, pression de service, variation de vitesse, récupération de chaleur."}, {"id": "e-7q689r9w", "title": "Vapeur et eau chaude : brûleur micro-modulant, condensats, purgeurs, calorifugeage."}, {"id": "e-0ges5a3i", "title": "Moteurs, pompes et ventilateurs : variation électronique de vitesse à charge variable."}]}], "intro": "", "title": "Utilités industrielles : où se trouve le gisement"}, "type": "checklist", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-d34z4ten", "data": {"html": "<h2>L'audit énergétique réglementaire</h2><p>Au-delà de 2,75 GWh consommés par an, l'audit énergétique devient obligatoire tous les quatre ans pour les entreprises sans système de management de l'énergie certifié. Mené avec notre partenaire Leo Energy, qualifié OPQIBI 1717 pour l'industrie, il ne s'arrête pas au rapport : chaque action recommandée est chiffrée avec sa fiche CEE et peut être réalisée par PEXEN.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-xw6i9tpg", "data": {"items": [{"id": "f-wu6q3r45", "answer": "<p>Oui. Les fournitures sont préparées en amont pour concentrer les raccordements sur la fenêtre d’arrêt.</p>", "question": "Pouvez-vous intervenir pendant un arrêt technique court ?"}, {"id": "f-woxwubfs", "answer": "<p>En général : calorifugeage des points singuliers, régulation du froid et variation de vitesse. Le relevé le confirme pour votre site.</p>", "question": "Quelles actions sont les plus rapides à rentabiliser ?"}, {"id": "f-lkr0bexs", "answer": "<p>Oui si sa consommation annuelle moyenne atteint 2,75 GWh et qu’il ne dispose pas d’un système de management de l’énergie certifié ISO 50001.</p>", "question": "Mon site est-il soumis à l’audit énergétique obligatoire ?"}], "title": "Questions fréquentes sur l’efficacité énergétique industrielle", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-6195gvcc", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-w4w2p1cd", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-ateibbwa", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "secteurs/efficacite-energetique-industrielle", "noindex": false, "nofollow": false, "seoTitle": "Efficacité énergétique industrielle : froid, chaleur | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "efficacité énergétique industrielle", "metaDescription": "Efficacité énergétique industrielle : froid process, chaleur fatale, vapeur, calorifugeage. Études et travaux sans arrêt de production, fiches CEE IND-UT."}	16	2026-10-21 12:43:13.022+02	\N	2026-10-21 12:43:13.022+02	2026-11-03 13:19:01.627+01	\N
page-yexaejjt	/secteurs/renovation-energetique-copropriete/	Bâtiments collectifs	published	cms	default	[{"id": "b-aktvm7cn", "data": {"image": "/themes/ultra-s/images/pexen/chaufferie-de-batiments-collectifs-modernisee-par-pexen.webp", "intro": "Bailleurs sociaux, syndics et gestionnaires de copropriété : la rénovation énergétique copropriété et logement social agit sur deux choses que les occupants ressentent chaque hiver, leurs charges et leur confort. PEXEN modernise les chaufferies collectives, remplace le fioul par des pompes à chaleur, équilibre les réseaux et monte les dossiers CEE, dont la rénovation globale BAR-TH-177.", "title": "Performance énergétique des bâtiments collectifs", "buttons": [{"id": "btn-dsz4ym6b", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-gyqk21ds", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Secteurs", "metrics": [{"id": "m-ev7tfk08", "label": "âge à partir duquel un plan pluriannuel de travaux est requis", "value": "15 ans"}, {"id": "m-j2oz2sfv", "label": "installateur de pompes à chaleur collectives", "value": "RGE QualiPAC"}, {"id": "m-gskvunyj", "label": "prêt pour l’assemblée générale", "value": "1 dossier"}], "imageAlt": "Chaufferie collective, rénovation énergétique copropriété", "highlight": "Des charges maîtrisées, un confort tenu, un dossier prêt pour la décision.", "breadcrumb": true, "parentLink": "/secteurs/", "heroVariant": "sector", "parentLabel": "Secteurs"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "md"}}, {"id": "b-dkws7ohs", "data": {"intro": "", "items": [{"id": "c-ldf2exw2", "link": "", "tags": [], "text": "Le chauffage et l’eau chaude collectifs constituent le premier poste de charges récupérables.", "title": "Les charges des occupants", "imageAlt": "Les charges des occupants", "linkLabel": ""}, {"id": "c-f1bxtlj7", "link": "", "tags": [], "text": "Chaudières fioul ou gaz hors condensation, réseaux non isolés, régulation figée : les rendements chutent.", "title": "Des chaufferies vieillissantes", "imageAlt": "Des chaufferies vieillissantes", "linkLabel": ""}, {"id": "c-r6m7pwhd", "link": "", "tags": [], "text": "Un projet de copropriété se vote en assemblée générale : il exige un dossier technique et financier lisible.", "title": "Une décision collective", "imageAlt": "Une décision collective", "linkLabel": ""}], "style": "hoverDark", "title": "Vos enjeux de bailleur ou de syndic", "columns": 3, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-u2j6g6yr", "data": {"intro": "", "items": [{"id": "c-7rq2knqq", "link": "", "tags": ["BAT-TH-163", "BAT-TH-164", "BAT-TH-162"], "text": "Pompes à chaleur collectives et géothermie, bonifiées par le Coup de pouce Chauffage en cas de dépose d’une chaudière fossile. PEXEN est installateur RGE QualiPAC.", "image": "/themes/ultra-s/images/pexen/pompes-a-chaleur-air-eau-sortie-du-fioul-chez-intermarche.webp", "title": "Sortie du fioul et du gaz", "imageAlt": "Sortie du fioul et du gaz", "linkLabel": ""}, {"id": "c-2yepkd9v", "link": "", "tags": ["BAR-SE-104"], "text": "Réglage des organes d’équilibrage d’une installation de chauffage à eau chaude : les logements éloignés de la chaufferie atteignent la consigne sans surchauffer les autres.", "image": "/themes/ultra-s/images/pexen/batiments-collectifs-chaufferie-pexen.webp", "title": "Équilibrage et régulation des réseaux", "imageAlt": "Équilibrage et régulation des réseaux", "linkLabel": ""}, {"id": "c-b3acj8wo", "link": "", "tags": ["IND-UT-131", "IND-UT-121"], "text": "Calorifugeage des réseaux et matelas isolants sur vannes et échangeurs.", "image": "/themes/ultra-s/images/pexen/drive-isolation-technique-sur-reseau-hvac-industriel.webp", "title": "Isolation technique en chaufferie", "imageAlt": "Isolation technique en chaufferie", "linkLabel": ""}, {"id": "c-zip1fpge", "link": "", "tags": ["BAR-TH-177"], "text": "Audit, bouquet de travaux et financement par la fiche BAR-TH-177, avec une bonification Coup de pouce « Rénovation performante d’un bâtiment résidentiel collectif » prolongée jusqu’au 31 décembre 2030.", "image": "/themes/ultra-s/images/pexen/drive-secteur-renovation-globale-collectif.webp", "title": "Rénovation globale", "imageAlt": "Rénovation globale", "linkLabel": ""}], "style": "hoverDark", "title": "Nos solutions pour la rénovation énergétique copropriété", "columns": 2, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-b77gtrn3", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-1jpumpep", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-1hmi4cre", "data": {"html": "<h2>Un dossier prêt pour l'assemblée générale</h2><p>Nous remettons un dossier lisible par le conseil syndical ou la direction du patrimoine : état des lieux, scénarios chiffrés, montant des CEE, reste à charge par lot ou par logement, calendrier des travaux en site occupé.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-70d190g0", "data": {"html": "<h2>Les obligations des copropriétés</h2><p>Depuis la loi Climat et résilience, les copropriétés de plus de 15 ans doivent disposer d'un projet de plan pluriannuel de travaux, et les immeubles en monopropriété ou en copropriété d'un diagnostic de performance énergétique collectif. Le calendrier s'est appliqué par taille de copropriété : de 2023 à 2025 pour le plan pluriannuel, de 2024 à 2026 pour le DPE collectif. Depuis le 1er janvier 2026, toutes les copropriétés sont concernées. Ces documents chiffrent les travaux ; notre étude les traduit en scénarios finançables.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-jf5t1gcv", "data": {"text": "", "title": "Parlons de votre projet", "layout": "centered", "buttons": [{"id": "btn-ep0pcivv", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-350vk09v", "data": {"intro": "", "items": [{"id": "s-g5eiftif", "num": "01", "text": "Consommations, puissance installée et températures de départ.", "title": "Relevé"}, {"id": "s-n241jz75", "num": "02", "text": "Pompe à chaleur seule, hybride avec appoint, géothermie.", "title": "Scénarios"}, {"id": "s-zf7fn04e", "num": "03", "text": "Assemblée générale ou comité d’engagement, avec le montant des CEE.", "title": "Dossier"}, {"id": "s-qt6d08d0", "num": "04", "text": "Hors saison de chauffe ou avec production provisoire.", "title": "Travaux"}, {"id": "s-2h5968tx", "num": "05", "text": "Réglage, équilibrage et suivi de la première saison.", "title": "Suivi"}], "style": "timeline", "title": "Sortir du fioul en chaufferie collective", "buttons": [], "eyebrow": "Méthode", "deliverableLabel": "Livrable"}, "type": "steps", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-xupeq2my", "data": {"html": "<h2>Bailleurs, syndics, gestionnaires : un dossier adapté à chacun</h2><p>Pour un bailleur social, nous raisonnons à l'échelle du patrimoine et du programme pluriannuel. Pour un syndic, nous préparons les éléments que le conseil syndical présentera aux copropriétaires. Pour un gestionnaire, nous suivons les consommations après travaux et ajustons les réglages de la chaufferie.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-n7b5w2pt", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-6advaob4", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-noe68462", "data": {"items": [{"id": "f-e35cdv3z", "answer": "<p>Oui. Le remplacement d’une production de chaleur se planifie hors saison de chauffe ou avec une solution provisoire.</p>", "question": "Les travaux se font-ils en site occupé ?"}, {"id": "f-3kupbt29", "answer": "<p>Le syndicat des copropriétaires, maître d’ouvrage des travaux. La prime vient en déduction du coût voté.</p>", "question": "Qui perçoit la prime CEE en copropriété ?"}, {"id": "f-hp02xafm", "answer": "<p>Oui, de l’étude du patrimoine à la réalisation, avec un dossier CEE par opération.</p>", "question": "Travaillez-vous avec les bailleurs sociaux ?"}, {"id": "f-m2r2peme", "answer": "<p>Oui. La modernisation (régulation, équilibrage, isolation) ou le remplacement par pompe à chaleur se dimensionnent selon le site.</p>", "question": "Pouvez-vous intervenir sur une chaufferie au gaz ?"}], "title": "Questions fréquentes sur la rénovation énergétique en copropriété", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-oi6gs1za", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-crguiv4x", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-nmw8a8ci", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "secteurs/renovation-energetique-copropriete", "noindex": false, "nofollow": false, "seoTitle": "Rénovation énergétique des bâtiments collectifs | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "rénovation énergétique", "metaDescription": "Rénovation énergétique copropriété et logement social : sortie du fioul, chaufferie collective, équilibrage, dossiers CEE et AG."}	18	2026-10-18 13:23:13.999+02	\N	2026-10-18 13:23:13.999+02	2026-11-03 13:19:01.628+01	\N
p-o4kdsmj3	/expertises/assistance-maitrise-ouvrage/	Accompagnement travaux	published	cms	default	[{"id": "b-t9f688zc", "data": {"image": "/themes/ultra-s/images/pexen/pexen-partenaire-installateur-livraison-d-equipements-sur-chantier.webp", "intro": "Un projet énergétique se gagne aussi sur le chantier. Notre assistance à maîtrise d'ouvrage décharge vos équipes : nous vérifions la faisabilité, planifions les travaux, suivons le chantier et constituons le dossier jusqu'au contrôle.", "title": "Accompagnement travaux, de la faisabilité au contrôle", "buttons": [{"id": "btn-akckvbcg", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-rdfaya00", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Expertises", "metrics": [{"id": "m-h3uyeo3c", "label": "du relevé au dossier soldé", "value": "5 étapes"}, {"id": "m-7qcfz5ry", "label": "travaux phasés, de nuit ou par zone", "value": "Site ouvert"}, {"id": "m-yn2e0lvm", "label": "contrôle par un organisme accrédité", "value": "COFRAC"}], "imageAlt": "Accompagnement travaux, de la faisabilité au contrôle", "breadcrumb": true, "parentLink": "/expertises/", "heroVariant": "expertise", "parentLabel": "Expertises"}, "type": "pageHeader", "style": {"background": "surface", "paddingBottom": "md"}}, {"id": "b-b2hzas9i", "data": {"intro": "Un seul interlocuteur du premier relevé jusqu'à la prise en charge complète du dossier.", "items": [{"id": "s-vzslrjvd", "num": "01", "text": "Audit énergétique, relevés sur site et calcul du gisement. Étude de faisabilité technique et vérification de l'éligibilité aux dispositifs de financement.", "title": "Étude et éligibilité"}, {"id": "s-lswsnpbq", "num": "02", "text": "Notes de dimensionnement, choix des équipements, devis et plan de financement. Planning des travaux et organisation de l'assistance à maîtrise d'ouvrage.", "title": "Ingénierie et planification"}, {"id": "s-l57t2ua3", "num": "03", "text": "Installation par nos équipes, suivi de chantier et AMO, mise en service et réglages, sans interrompre l'exploitation.", "title": "Travaux et suivi de chantier"}, {"id": "s-95jxz7jt", "num": "04", "text": "Documents de fin de travaux et procès-verbal de réception. Pour les opérations CEE : contrôle par un organisme accrédité COFRAC.", "title": "Fin de travaux et contrôle"}, {"id": "s-1wzc7bne", "num": "05", "text": "Rapport final et suivi du dossier de financement jusqu'à la prise en charge complète. Suivi des consommations après travaux.", "title": "Prise en charge et suivi"}], "style": "timeline", "title": "Le parcours en 5 étapes", "buttons": [], "eyebrow": "Parcours", "phaseBanner": "Avant travaux (01, 02) · Pendant les travaux (03) · Après travaux (04, 05)", "deliverableLabel": ""}, "type": "steps", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-r59nqny1", "data": {"html": "<p>Un supermarché ne ferme pas, une ligne de production ne s'arrête qu'à date fixe, un bâtiment collectif reste habité. Chaque planning est construit avec l'exploitant : interventions de nuit ou hors heures d'ouverture, phasage par circuit frigorifique, solutions de chauffage provisoires, consignation et plans de prévention.</p>", "image": "/themes/ultra-s/images/pexen/drive-equipe-pexen.webp", "ratio": "landscape", "title": "Travailler en site occupé", "bullets": ["Site occupé"], "buttons": [{"id": "btn-j88sc0gc", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "eyebrow": "Exploitation", "autoplay": false, "imageAlt": "Équipe PEXEN sur site occupé", "highlight": "", "mediaType": "image", "mediaStyle": "framed", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-n3nz9zb1", "data": {"items": [{"id": "c-zjp9pv2i", "tags": [], "text": "Respect du planning et des fenêtres d'intervention.", "title": "Planning"}, {"id": "c-ekm0pkom", "tags": [], "text": "Équipements posés conformes aux exigences techniques retenues.", "title": "Conformité"}, {"id": "c-25xt8p4v", "tags": [], "text": "Complétude du dossier de fin de travaux.", "title": "Dossier"}, {"id": "c-mue92stw", "tags": [], "text": "Résultat du contrôle et corrections éventuelles.", "title": "Contrôle"}], "style": "minimal", "title": "Ce que nous suivons sur chaque chantier", "columns": 2, "eyebrow": "Suivi", "headerLink": "", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "surface", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-29ni67t8", "data": {"items": [{"id": "f-6u5mtzs4", "answer": "<p>Un organisme accrédité vérifie sur site que les travaux réalisés correspondent aux études et aux exigences techniques de l'opération.</p>", "question": "Que vérifie le contrôle COFRAC ?"}, {"id": "f-zii8c0fl", "answer": "<p>Oui. Les travaux sont phasés par zone, par circuit ou pendant vos arrêts programmés.</p>", "question": "Pouvez-vous intervenir sans fermer le site ?"}, {"id": "f-qiphetbe", "answer": "<p>Oui. Nous coordonnons votre mainteneur, votre bureau d'études ou votre maître d'œuvre lorsqu'ils interviennent sur le projet.</p>", "question": "Travaillez-vous avec nos prestataires en place ?"}, {"id": "f-w2ks08ae", "answer": "<p>Nos équipes, avec le fabricant lorsque l'équipement l'exige. Les réglages et essais figurent au procès-verbal de réception.</p>", "question": "Qui assure la mise en service ?"}, {"id": "f-vygi05la", "answer": "<p>De quelques jours pour une déstratification à plusieurs semaines pour une chaufferie ou une centrale froid.</p>", "question": "Combien de temps dure un chantier ?"}], "title": "Questions fréquentes sur l'accompagnement travaux", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-fchhnv7m", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-2z34bhfo", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-41mwnp3x", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "accompagnement-travaux", "noindex": false, "nofollow": false, "seoTitle": "Assistance à maîtrise d'ouvrage et suivi de chantier | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "assistance à maîtrise d'ouvrage", "metaDescription": "Assistance à maîtrise d'ouvrage pour vos travaux énergétiques : faisabilité, planification, suivi de chantier, documents de fin de travaux et contrôle COFRAC."}	20	2026-10-21 12:43:13.022+02	\N	2026-10-21 12:43:13.022+02	2026-10-30 08:47:32.779+01	\N
p-7e3yofgg	/simulateur-prime-cee/	Estimer le financement	published	cms	default	[{"id": "b-pro0azqd", "data": {"image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "intro": "Décrivez votre site et les travaux envisagés : vous obtenez un premier ordre de grandeur du financement des travaux énergétiques mobilisable. Il ne remplace ni la visite technique, ni les relevés, ni la note de calcul : un ingénieur PEXEN l’établit ensuite à partir de votre installation réelle.", "title": "Estimez le financement de votre projet", "buttons": [], "eyebrow": "PEXEN", "breadcrumb": true, "parentLink": "", "parentLabel": "", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-jamgy2bw", "data": {"align": "left", "intro": "", "title": "Décrivez votre site et les travaux envisagés", "formId": "contact-main", "eyebrow": "Financement", "howText": "Chaque action correspond à une opération standardisée qui fixe un volume d’économies selon le secteur, la zone climatique et la puissance installée. Ce volume est valorisé au prix du marché ; des bonifications s’appliquent pour la sortie des énergies fossiles ou un contrat de performance énergétique.", "regions": [{"id": "idf", "label": "Île-de-France", "factor": 1.05}, {"id": "hdf", "label": "Hauts-de-France", "factor": 1.08}, {"id": "ge", "label": "Grand Est", "factor": 1.08}, {"id": "nor", "label": "Normandie", "factor": 1.05}, {"id": "bre", "label": "Bretagne", "factor": 1}, {"id": "pdl", "label": "Pays de la Loire", "factor": 1}, {"id": "cvl", "label": "Centre-Val de Loire", "factor": 1.02}, {"id": "bfc", "label": "Bourgogne-Franche-Comté", "factor": 1.06}, {"id": "naq", "label": "Nouvelle-Aquitaine", "factor": 0.95}, {"id": "occ", "label": "Occitanie", "factor": 0.9}, {"id": "ara", "label": "Auvergne-Rhône-Alpes", "factor": 1.04}, {"id": "pac", "label": "Provence-Alpes-Côte d’Azur", "factor": 0.88}, {"id": "cor", "label": "Corse", "factor": 0.85}], "variant": "tool", "ctaLabel": "Envoyer ma demande", "energies": [{"id": "fioul", "label": "Fioul", "factor": 1.25}, {"id": "gaz", "label": "Gaz", "factor": 1.12}, {"id": "electricite", "label": "Électricité", "factor": 1}, {"id": "reseau", "label": "Réseau de chaleur", "factor": 0.95}], "howTitle": "Comment le financement des travaux énergétiques est-il estimé ?", "siteTypes": [{"id": "supermarche", "label": "Supermarché", "factor": 1.15}, {"id": "bureaux", "label": "Bureaux", "factor": 0.85}, {"id": "entrepot", "label": "Entrepôt", "factor": 1}, {"id": "hotel", "label": "Hôtel", "factor": 0.95}, {"id": "sante", "label": "Santé", "factor": 1.05}, {"id": "industriel", "label": "Site industriel", "factor": 1.2}, {"id": "collectif", "label": "Bâtiment collectif", "factor": 0.9}], "disclaimer": "* Première estimation indicative, sans valeur contractuelle : le dimensionnement et le montant définitif sont établis après analyse du site.", "operations": [{"id": "pac", "label": "Pompe à chaleur", "maxPerKw": 110, "maxPerM2": 22, "minPerKw": 40, "minPerM2": 8}, {"id": "recup", "label": "Récupération de chaleur", "maxPerKw": 90, "maxPerM2": 32, "minPerKw": 30, "minPerM2": 12}, {"id": "froid", "label": "Régulation du froid", "maxPerKw": 80, "maxPerM2": 20, "minPerKw": 25, "minPerM2": 8}, {"id": "meubles", "label": "Fermeture des meubles frigorifiques", "maxPerM2": 40, "minPerM2": 15}, {"id": "destrat", "label": "Déstratification", "maxPerM2": 12, "minPerM2": 4}, {"id": "gtb", "label": "GTB", "maxPerM2": 16, "minPerM2": 5}, {"id": "isolation", "label": "Isolation", "maxPerM2": 20, "minPerM2": 7}, {"id": "led", "label": "Éclairage LED", "maxPerM2": 10, "minPerM2": 3}], "resultNote": "Un ingénieur PEXEN affine cette estimation lors d’un premier échange.", "teaserNote": "Première estimation indicative : le dimensionnement est établi après analyse du site.", "contactText": "Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.", "privacyPath": "/politique-de-confidentialite/", "contactTitle": "Un projet ? Parlons-en.", "resultPrefix": "Financement estimé", "teaserCtaLink": "/simulateur-prime-cee/", "teaserCtaLabel": "Estimer le financement"}, "type": "simulator", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "estimation-financement", "noindex": false, "nofollow": false, "seoTitle": "Financement des travaux énergétiques : estimation | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "financement des travaux énergétiques", "metaDescription": "Estimez le financement de vos travaux énergétiques : type de site, travaux envisagés, puissance. Première estimation indicative, établie ensuite après analyse du site."}	23	2026-10-21 12:43:13.022+02	\N	2026-10-21 12:43:13.022+02	2026-10-30 08:47:32.777+01	\N
p-42a6ctxq	/secteurs/efficacite-energetique-tertiaire/	Tertiaire	published	cms	default	[{"id": "b-wm7hpmzk", "data": {"image": "/themes/ultra-s/images/pexen/efficacite-energetique-des-batiments-tertiaires.webp", "intro": "Grande distribution, bureaux, entrepôts logistiques, établissements de santé : l’efficacité énergétique tertiaire répond désormais à une trajectoire chiffrée. Le décret tertiaire impose −40 % de consommation en 2030 à tout bâtiment de 1 000 m² et plus. PEXEN traite d’abord les postes qui pèsent le plus, froid commercial, chauffage des grands volumes et pilotage, pour bâtir un plan d’actions que vous pouvez défendre devant votre direction.", "title": "Efficacité énergétique des bâtiments tertiaires", "buttons": [{"id": "btn-3eyuvyep", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-s5oy0g0a", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Secteurs", "metrics": [{"id": "m-we7fx42i", "label": "en 2030, puis −50 % en 2040 et −60 % en 2050", "value": "−40 %"}, {"id": "m-n5ndoe15", "label": "seuil d’assujettissement", "value": "1 000 m²"}, {"id": "m-y5lq30oe", "label": "déclaration annuelle sur OPERAT", "value": "30 septembre"}], "imageAlt": "Supermarché accompagné par PEXEN en efficacité énergétique tertiaire", "highlight": "Le décret tertiaire a une date. Votre plan d’actions aussi.", "breadcrumb": true, "parentLink": "/secteurs/", "heroVariant": "sector", "parentLabel": "Secteurs"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "md"}}, {"id": "b-wb59b9vc", "data": {"intro": "", "items": [{"id": "c-3ly6317w", "link": "", "tags": [], "text": "−40 % en 2030, −50 % en 2040, −60 % en 2050, déclaration annuelle sur OPERAT avant le 30 septembre.", "title": "Le décret tertiaire", "imageAlt": "Le décret tertiaire", "linkLabel": ""}, {"id": "c-e205sf5m", "link": "", "tags": [], "text": "GTB obligatoire au-delà de 290 kW depuis 2025, au-delà de 70 kW au 1er janvier 2030.", "title": "Le décret BACS", "imageAlt": "Le décret BACS", "linkLabel": ""}, {"id": "c-1epaln7m", "link": "", "tags": [], "text": "Dans un supermarché, le froid représente 45 à 75 % des dépenses d’énergie ; dans un entrepôt ou un magasin de grande hauteur, la chaleur s’accumule sous la toiture.", "title": "Le poids du froid et des grands volumes", "imageAlt": "Le poids du froid et des grands volumes", "linkLabel": ""}], "style": "hoverDark", "title": "Vos enjeux dans le tertiaire", "columns": 3, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-x2t4tfiy", "data": {"intro": "", "items": [{"id": "c-ywxo7nvc", "link": "", "tags": [], "text": "Régulation haute et basse pression flottante, fermeture des meubles, récupération de chaleur sur la centrale froid, pompe à chaleur, GTB.", "image": "/themes/ultra-s/images/pexen/drive-froid-commercial-industriel.webp", "title": "Grande distribution", "imageAlt": "Grande distribution", "linkLabel": ""}, {"id": "c-9me7kh5r", "link": "", "tags": [], "text": "GTB de classe A ou B, pompes à chaleur, équilibrage et régulation des réseaux, isolation des toitures-terrasses.", "image": "/themes/ultra-s/images/pexen/drive-pilotage-gtb-gtc.webp", "title": "Bureaux", "imageAlt": "Bureaux", "linkLabel": ""}, {"id": "c-i44zaolt", "link": "", "tags": [], "text": "Déstratification d’air, remplacement des aérothermes gaz, isolation de toiture.", "image": "/themes/ultra-s/images/pexen/destratificateur-d-air-installe-dans-un-magasin-de-grande-hauteur.webp", "title": "Entrepôts et magasins de grande hauteur", "imageAlt": "Entrepôts et magasins de grande hauteur", "linkLabel": ""}, {"id": "c-j6qw57bp", "link": "", "tags": [], "text": "Production d’eau chaude sanitaire, récupération de chaleur sur eaux grises, pilotage des centrales de traitement d’air.", "image": "/themes/ultra-s/images/pexen/drive-recuperateur-de-chaleur.webp", "title": "Santé et hébergement", "imageAlt": "Santé et hébergement", "linkLabel": ""}], "style": "hoverDark", "title": "Nos interventions par type de bâtiment tertiaire", "columns": 2, "eyebrow": "Solutions", "headerLinkLabel": ""}, "type": "cards", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-2sdnd8n9", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-an6l4135", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-aapbxgmt", "data": {"html": "<h2>Construire votre trajectoire décret tertiaire</h2><p>Nous partons de votre année de référence déclarée sur OPERAT, nous chiffrons l'écart avec l'objectif 2030 et nous classons les actions par gain et par temps de retour, CEE déduits. Le plan d'actions sert ensuite de base aux déclarations annuelles.</p><p><a href=\\"/expertises/financement-cee-reglementation/\\">Réglementation et financement CEE</a></p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-mvqnoneb", "data": {"html": "<h2>Le cas de la grande distribution</h2><p>Selon les déclarations OPERAT 2023, un supermarché de 400 à 2 500 m² consomme en moyenne 264 à 281 kWh par m² et par an. L'écart vient des rayons froids : environ 979 kWh/m²/an pour un rayon réfrigéré, contre 45 à 72 kWh/m²/an pour un rayon sec. Notre ordre d'intervention suit ce constat : régulation du froid, fermeture des meubles, récupération de chaleur, puis chauffage et pilotage.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-pxvmqlml", "data": {"text": "", "title": "Parlons de votre projet", "layout": "centered", "buttons": [{"id": "btn-c0vjhumb", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-wr73l1o0", "data": {"html": "<h2>Propriétaires et exploitants : qui décide quoi</h2><p>Le décret tertiaire engage le propriétaire et l'occupant. Les équipements de l'exploitant, comme le froid commercial, relèvent souvent du locataire ; l'enveloppe et la chaufferie, du propriétaire. Nous construisons un plan d'actions qui sépare clairement les deux périmètres, pour que chacun déclare ses consommations et finance ses travaux.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-hz9az8n9", "data": {"html": "<h2>Réalisations dans le tertiaire</h2><ul><li><a href=\\"/realisations/\\">Intermarché · Bourgogne-Franche-Comté</a> : 14,8 GWh cumac estimés*</li><li><a href=\\"/realisations/\\">Carrefour Market · Île-de-France</a> : 30,6 GWh cumac estimés* · objectif contractuel −40 %</li><li><a href=\\"/realisations/\\">CEDIM · Centre-Val de Loire</a> : 2,1 GWh cumac estimés*</li></ul>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-rsyezngj", "data": {"html": "<p class=\\"text-xs text-slate-500\\">* Estimation calculée selon les fiches d’opérations standardisées CEE mobilisées (arrêté du 22 décembre 2014 modifié). Le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements ; il ne mesure pas les consommations réelles.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-091b29it", "data": {"items": [{"id": "f-4ynwvm8p", "answer": "<p>Les deux. Ils se répartissent les actions selon le bail et déclarent sur OPERAT pour la part qui les concerne.</p>", "question": "Qui est responsable du décret tertiaire : le propriétaire ou le locataire ?"}, {"id": "f-udfabtau", "answer": "<p>Elle peut être corrigée sur OPERAT. Nous vérifions sa cohérence avec vos factures avant de bâtir la trajectoire.</p>", "question": "Que faire si mon année de référence est mal renseignée ?"}, {"id": "f-x93o99l1", "answer": "<p>Oui. Le décret porte sur toutes les consommations d’énergie finale du bâtiment, froid alimentaire compris.</p>", "question": "Les travaux de froid commercial comptent-ils pour le décret tertiaire ?"}, {"id": "f-l5av5hgb", "answer": "<p>Oui si la puissance nominale cumulée de ses systèmes de chauffage ou de climatisation dépasse 290 kW, et à partir de 2030 au-delà de 70 kW.</p>", "question": "Mon magasin est-il soumis au décret BACS ?"}, {"id": "f-tnjrzyu9", "answer": "<p>Le pilotage d’abord : horaires, consignes et réduits de nuit. Viennent ensuite la production de chaleur et de froid, puis l’enveloppe.</p>", "question": "Par quelles actions commencer dans un immeuble de bureaux ?"}], "title": "Questions fréquentes sur l’efficacité énergétique tertiaire", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-fsxc8zby", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-qnkiqe2y", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-weeluhrp", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "secteurs/efficacite-energetique-tertiaire", "noindex": false, "nofollow": false, "seoTitle": "Efficacité énergétique tertiaire et décret tertiaire | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "efficacité énergétique tertiaire", "metaDescription": "Efficacité énergétique tertiaire : grande distribution, bureaux, entrepôts, santé. Atteignez −40 % en 2030 avec le froid, la GTB et le chauffage."}	17	2026-10-21 12:43:13.022+02	\N	2026-10-21 12:43:13.022+02	2026-11-03 13:19:01.627+01	\N
p-zhfrekzi	/mentions-legales/	Mentions légales	published	cms	legal	[{"id": "b-vx643myc", "data": {"image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "intro": "", "title": "Mentions légales", "buttons": [], "eyebrow": "PEXEN", "breadcrumb": true, "parentLink": "", "parentLabel": "", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-oi2g9pcu", "data": {"html": "<p><em>Dernière mise à jour : 22 octobre 2026</em></p>\\n<h2>1. Éditeur du site</h2>\\n<p>Le site pexen.fr (ci-après « le Site ») est édité par la société PEXEN, société par actions simplifiée au capital de 30 000 euros, immatriculée au registre du commerce et des sociétés de Bobigny sous le numéro 922 217 336, dont le siège social est situé 111 AVENUE VICTOR HUGO 93300 AUBERVILLIERS (SIRET : 922 217 336 00028).</p>\\n<p>Numéro de TVA intracommunautaire : FR75922217336</p>\\n<p>Téléphone : 01 41 93 52 80</p>\\n<p>Adresse électronique : contact@pexen.fr</p>\\n<p>PEXEN® est une marque de la société PEXEN.</p>\\n<h2>2. Directeur de la publication</h2>\\n<p>Monsieur Jamel Yacouben, en sa qualité de Président de la société PEXEN.</p>\\n<h2>3. Hébergement</h2>\\n<p>Le Site est hébergé par IONOS.</p>\\n<h2>4. Qualifications et assurances</h2>\\n<p>PEXEN est titulaire des qualifications RGE QualiPAC (pompes à chaleur, chauffage et eau chaude sanitaire), certificat n° QPAC/70449, et RGE Qualisol CESI, certificat n° QS/70449, délivrées par Qualit&#x27;EnR. Leur validité peut être vérifiée sur l&#x27;annuaire officiel France Rénov&#x27;.</p>\\n<p>Les audits énergétiques mentionnés sur le Site sont réalisés par le bureau d&#x27;études partenaire Leo Energy, titulaire de qualifications OPQIBI. Ces qualifications appartiennent à Leo Energy et non à PEXEN.</p>\\n<p>PEXEN a souscrit une assurance de responsabilité civile professionnelle et une assurance de responsabilité civile décennale auprès de MIC Insurance Company (police n° PTF N-3898616), couvrant les travaux réalisés en France métropolitaine.</p>\\n<h2>5. Propriété intellectuelle</h2>\\n<p>L&#x27;ensemble des éléments composant le Site, notamment les textes, visuels, photographies, illustrations, schémas, vidéos, éléments graphiques, chartes graphiques, logiciels, bases de données, la marque déposée PEXEN®, ainsi que la structure, l&#x27;agencement et la présentation du Site, sont la propriété exclusive et intégrale de la société PEXEN ou font l&#x27;objet d&#x27;autorisations d&#x27;utilisation spécifiques accordées à celle-ci.</p>\\n<p>Toute reproduction, représentation, modification, adaptation, altération, traduction, extraction, réutilisation, diffusion ou exploitation, totale ou partielle, de ces éléments, de la marque PEXEN® ou de tout ou partie du contenu du Site, par quelque procédé que ce soit, sur quel que support que ce soit, sans l&#x27;autorisation écrite, préalable et expresse de la société PEXEN, est strictement interdite. Tout manquement constitue une contrefaçon sanctionnée par les articles L. 335-2 et suivants ainsi que L. 716-1 et suivants du Code de la propriété intellectuelle, susceptible d&#x27;engager la responsabilité civile et pénale de son auteur. PEXEN se réserve le droit d&#x27;engager toute poursuite judiciaire nécessaire à la préservation de ses droits.</p>\\n<p>Les noms et logos des clients figurant sur le Site sont reproduits avec leur accord. Les logos des organismes de qualification appartiennent à ces organismes.</p>\\n<h2>6. Informations techniques, chiffres et estimations</h2>\\n<p>Les informations, éléments graphiques, données techniques et outils de simulation publiés sur le Site sont fournis exclusivement à titre informatif et indicatif. Ils ne constituent en aucun cas une offre contractuelle, un conseil juridique, financier ou technique engagé, ni une garantie de résultat ou d&#x27;éligibilité. Seule une étude de faisabilité sur site réalisée par nos équipes et la signature d&#x27;un devis ou d&#x27;un contrat ferme engagent PEXEN.</p>\\n<p>Les estimations d&#x27;économies d&#x27;énergie (exprimées en kWh cumac, GWh cumac ou pourcentages) sont établies à titre théorique et indicatif selon les fiches d&#x27;opérations standardisées de certificats d&#x27;économies d&#x27;énergie (CEE) ou des modèles de simulation. Elles ne constituent en aucun cas un engagement ferme ou une mesure des consommations réelles. PEXEN exclut toute responsabilité en cas d&#x27;écart entre les estimations affichées et les économies réellement constatées ultérieurement.</p>\\n<p>Les pourcentages de réduction des consommations associés à un contrat de performance énergétique correspondent à des objectifs contractuels, définis sur un périmètre, une durée et des conditions d&#x27;exploitation déterminés dans le contrat concerné.</p>\\n<p>Les informations réglementaires (décret tertiaire, décret BACS, dispositif des certificats d&#x27;économies d&#x27;énergie) sont à jour à la date indiquée sur chaque page. Elles peuvent évoluer ; seuls les textes publiés au Journal officiel font foi.</p>\\n<h2>7. Responsabilité</h2>\\n<p>PEXEN s&#x27;efforce de maintenir le Site à jour et accessible, sans toutefois pouvoir garantir l&#x27;absence totale d&#x27;erreurs, de virus, d&#x27;interruptions techniques ou d&#x27;inexactitudes. Dans les limites autorisées par la loi, PEXEN décline toute responsabilité pour tout dommage direct ou indirect, matériel ou immatériel (incluant notamment les pertes de données, de chiffre d&#x27;affaires, de bénéfices ou d&#x27;opportunités) résultant de l&#x27;accès au Site, de son indisponibilité, ou de l&#x27;utilisation des informations et simulations qui y figurent.</p>\\n<h2>8. Liens hypertextes</h2>\\n<p>Le Site peut contenir des liens vers des sites tiers, notamment des sites institutionnels. PEXEN n&#x27;exerce aucun contrôle sur ces sites et décline toute responsabilité quant à leur contenu.</p>\\n<p>La création d&#x27;un lien vers le Site est libre, à condition qu&#x27;il ne porte pas atteinte à l&#x27;image de PEXEN et qu&#x27;il ouvre le Site dans une nouvelle fenêtre. PEXEN peut demander la suppression de tout lien à tout moment.</p>\\n<h2>9. Données personnelles et cookies</h2>\\n<p>Le traitement des données personnelles collectées sur le Site et l&#x27;utilisation des cookies sont décrits dans la <a href=\\"/politique-de-confidentialite/\\">politique de confidentialité</a>, accessible depuis chaque page du Site.</p>\\n<h2>10. Droit applicable et juridiction</h2>\\n<p>Les présentes mentions légales sont régies par le droit français. Tout litige relatif au Site relève, à défaut de résolution amiable et sous réserve des règles de compétence impératives, des juridictions compétentes du ressort du siège social de PEXEN.</p>", "size": "normal"}, "type": "richText", "style": {"width": "narrow", "background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "mentions-legales", "noindex": true, "nofollow": false, "seoTitle": "Mentions légales | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "", "metaDescription": "Mentions légales du site pexen.fr : éditeur, directeur de la publication, hébergeur."}	5	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-10-21 14:32:24.684+02	\N
p-eo5wde86	/politique-de-confidentialite/	Politique de confidentialité	published	cms	legal	[{"id": "b-h8tr1e8i", "data": {"image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "intro": "", "title": "Politique de confidentialité", "buttons": [], "eyebrow": "PEXEN", "breadcrumb": true, "parentLink": "", "parentLabel": "", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-mrg7j489", "data": {"html": "<p><em>Dernière mise à jour : 22 octobre 2026</em></p>\\n<p>La présente politique informe les visiteurs du Site et les personnes qui contactent PEXEN de la manière dont leurs données personnelles sont traitées, conformément au règlement (UE) 2016/679 du 27 avril 2016 (« RGPD ») et à la loi n° 78-17 du 6 janvier 1978 relative à l&#x27;informatique, aux fichiers et aux libertés.</p>\\n<h2>1. Responsable du traitement</h2>\\n<p>Le responsable du traitement est la société PEXEN, société par actions simplifiée au capital de 30 000 euros, immatriculée au RCS de Bobigny sous le numéro 922 217 336 (SIRET : 922 217 336 00028), dont le siège social est situé 111 AVENUE VICTOR HUGO 93300 AUBERVILLIERS, représentée par son Président, Monsieur Jamel Yacouben.</p>\\n<p>Pour toute question relative à vos données : contact@pexen.fr. PEXEN n&#x27;a pas désigné de délégué à la protection des données, cette désignation n&#x27;étant pas obligatoire au regard de son activité.</p>\\n<h2>2. Données collectées</h2>\\n<p>Formulaire de contact : nom et prénom, société, fonction (facultatif), adresse électronique professionnelle, numéro de téléphone, profil (entreprise, bailleur ou syndic, partenaire professionnel), type de site et description du projet. Les champs obligatoires sont signalés par un astérisque ; sans eux, PEXEN ne peut pas traiter la demande.</p>\\n<p>Outil « Estimer le financement » : type de site, nature des travaux envisagés et caractéristiques techniques saisies. Ces données ne sont rattachées à une personne que si celle-ci transmet ensuite ses coordonnées.</p>\\n<p>Échanges via WhatsApp : numéro de téléphone, nom de profil et contenu des messages, lorsque vous choisissez ce canal.</p>\\n<p>Assistant « Conseil PXN » : questions saisies dans l&#x27;assistant. Il est demandé de n&#x27;y saisir aucune donnée personnelle.</p>\\n<p>Navigation : avec votre consentement uniquement, données de mesure d&#x27;audience (pages consultées, durée de visite, type d&#x27;appareil et de navigateur, localisation approximative déduite de l&#x27;adresse IP tronquée).</p>\\n<h2>3. Finalités et bases légales</h2>\\n<div class=\\"table-responsive\\"><table class=\\"table\\"><thead><tr><th scope=\\"col\\">Finalité</th><th scope=\\"col\\">Base légale</th></tr></thead><tbody><tr><td>Répondre à votre demande, organiser la visite technique et établir une proposition</td><td>Mesures précontractuelles prises à votre demande (article 6.1.b du RGPD)</td></tr><tr><td>Gérer la relation commerciale et l&#x27;exécution des contrats</td><td>Exécution du contrat (article 6.1.b)</td></tr><tr><td>Adresser aux professionnels des informations sur les offres de PEXEN en rapport avec leur activité</td><td>Intérêt légitime de PEXEN (article 6.1.f), avec faculté d&#x27;opposition à tout moment</td></tr><tr><td>Constituer les dossiers de financement et répondre aux contrôles lorsque l&#x27;opération relève du dispositif des certificats d&#x27;économies d&#x27;énergie</td><td>Obligation légale et exécution du contrat (articles 6.1.c et 6.1.b)</td></tr><tr><td>Mesurer l&#x27;audience du Site et en améliorer le contenu</td><td>Consentement (article 6.1.a), recueilli par le bandeau cookies</td></tr><tr><td>Assurer la sécurité du Site et prévenir les envois abusifs du formulaire</td><td>Intérêt légitime de PEXEN (article 6.1.f)</td></tr><tr><td>Respecter les obligations comptables et fiscales</td><td>Obligation légale (article 6.1.c)</td></tr></tbody></table></div>\\n<h2>4. Destinataires</h2>\\n<p>Les données sont destinées aux seules personnes habilitées de PEXEN, dans la limite de leurs attributions. Elles peuvent être communiquées à des prestataires agissant pour le compte de PEXEN en qualité de sous-traitants : l&#x27;hébergeur du Site IONOS, Google Ireland Limited (messagerie professionnelle et, avec votre accord, Google Analytics) et Meta Platforms Ireland Limited (WhatsApp), pour les échanges que vous initiez sur ce canal.</p>\\n<p>Lorsqu&#x27;un projet relève du dispositif des certificats d&#x27;économies d&#x27;énergie, les données nécessaires au dossier sont transmises au partenaire financeur de l&#x27;opération et à l&#x27;organisme de contrôle accrédité, dans le cadre prévu par la réglementation. Vous en êtes informé au moment de la constitution du dossier.</p>\\n<p>Les données ne sont ni vendues, ni louées, ni cédées à des tiers à des fins commerciales.</p>\\n<h2>5. Transferts hors de l&#x27;Union européenne</h2>\\n<p>L&#x27;utilisation de Google Analytics et de WhatsApp peut entraîner un transfert de données vers les États-Unis. Ces transferts sont encadrés par la décision d&#x27;adéquation de la Commission européenne relative au cadre de protection des données UE–États-Unis (Data Privacy Framework), à laquelle ces sociétés ont adhéré, et, à défaut, par les clauses contractuelles types de la Commission européenne.</p>\\n<h2>6. Durées de conservation</h2>\\n<div class=\\"table-responsive\\"><table class=\\"table\\"><thead><tr><th scope=\\"col\\">Données</th><th scope=\\"col\\">Durée</th></tr></thead><tbody><tr><td>Demande de contact sans suite</td><td>3 ans à compter du dernier contact émanant de la personne</td></tr><tr><td>Données des clients</td><td>Durée de la relation contractuelle, puis 3 ans à des fins de prospection ; durée de la prescription applicable pour la gestion d&#x27;un éventuel contentieux</td></tr><tr><td>Pièces des dossiers de travaux et de financement</td><td>Durée imposée par la réglementation applicable à l&#x27;opération</td></tr><tr><td>Pièces comptables</td><td>10 ans (article L. 123-22 du Code de commerce)</td></tr><tr><td>Cookies de mesure d&#x27;audience</td><td>13 mois au maximum à compter de leur dépôt</td></tr><tr><td>Données de mesure d&#x27;audience</td><td>14 mois</td></tr><tr><td>Choix exprimé dans le bandeau cookies</td><td>6 mois, au terme desquels votre choix est de nouveau demandé</td></tr></tbody></table></div>\\n<h2>7. Vos droits</h2>\\n<p>Vous disposez d&#x27;un droit d&#x27;accès, de rectification, d&#x27;effacement, de limitation du traitement, d&#x27;opposition, notamment à la prospection, et à la portabilité de vos données, ainsi que du droit de définir des directives relatives au sort de vos données après votre décès. Lorsque le traitement repose sur votre consentement, vous pouvez le retirer à tout moment, sans que cela remette en cause la licéité du traitement effectué avant ce retrait.</p>\\n<p>Pour exercer ces droits, écrivez à contact@pexen.fr. Une réponse vous est apportée dans un délai d&#x27;un mois, prolongeable de deux mois compte tenu de la complexité ou du nombre de demandes. Un justificatif d&#x27;identité peut vous être demandé en cas de doute raisonnable sur votre identité.</p>\\n<p>Si vous estimez, après avoir contacté PEXEN, que vos droits ne sont pas respectés, vous pouvez introduire une réclamation auprès de la Commission nationale de l&#x27;informatique et des libertés (CNIL), 3 place de Fontenoy, TSA 80715, 75334 Paris Cedex 07, <a href=\\"https://www.cnil.fr/\\" target=\\"_blank\\" rel=\\"noopener\\">www.cnil.fr</a>.</p>\\n<h2>8. Sécurité</h2>\\n<p>PEXEN met en œuvre des mesures techniques et organisationnelles renforcées et adaptées au risque pour préserver la sécurité, l&#x27;intégrité et la confidentialité des données personnelles et empêcher toute altération, perte ou accès non autorisé : protocole HTTPS chiffré, contrôle strict des accès réservés au seul personnel habilité, politiques de mots de passe renforcées et sélection de sous-traitants présentant des garanties suffisantes de conformité au RGPD.</p>\\n<h2>9. Cookies</h2>\\n<p>Un cookie est un fichier déposé sur votre terminal lors de la consultation du Site. Le Site utilise :</p>\\n<div class=\\"table-responsive\\"><table class=\\"table\\"><thead><tr><th scope=\\"col\\">Catégorie</th><th scope=\\"col\\">Finalité</th><th scope=\\"col\\">Consentement</th><th scope=\\"col\\">Durée</th></tr></thead><tbody><tr><td>Cookies nécessaires</td><td>Fonctionnement et sécurité du Site, mémorisation de votre choix en matière de cookies</td><td>Non requis</td><td>6 mois au maximum</td></tr><tr><td>Mesure d&#x27;audience (Google Analytics 4 : _ga, _ga_GRR10GDECY)</td><td>Statistiques de fréquentation et amélioration des contenus</td><td>Requis</td><td>13 mois au maximum</td></tr></tbody></table></div>\\n<p>Lors de votre première visite, un bandeau vous permet d&#x27;accepter, de refuser ou de paramétrer les cookies soumis à consentement. Refuser est aussi simple qu&#x27;accepter. Aucun cookie de mesure d&#x27;audience n&#x27;est déposé avant votre choix. Vous pouvez modifier ce choix à tout moment grâce au lien « Gérer mes cookies » présent en bas de chaque page.</p>\\n<p>Vous pouvez également configurer votre navigateur pour bloquer les cookies. Les cookies nécessaires restant indispensables au fonctionnement du Site, leur blocage peut en limiter certaines fonctionnalités.</p>\\n<h2>10. Modification de la politique</h2>\\n<p>PEXEN peut modifier la présente politique pour tenir compte des évolutions légales, réglementaires ou techniques. La date de dernière mise à jour figure en tête de page.</p>", "size": "normal"}, "type": "richText", "style": {"width": "narrow", "background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "politique-de-confidentialite", "noindex": true, "nofollow": false, "seoTitle": "Politique de confidentialité | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "", "metaDescription": "Comment PEXEN collecte, utilise et protège vos données personnelles."}	6	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-10-21 14:32:24.684+02	\N
p-ul37qalc	/realisations/colorcon-efficacite-energetique-industrielle/	Réalisation Colorcon	draft	cms	project	[{"id": "b-pku13rjw", "data": {"image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "intro": "Île-de-France · Industrie pharmaceutique · [À compléter par Abdou : statut : étude, travaux en cours ou réalisé]", "title": "Colorcon : efficacité énergétique industrielle d'un site pharmaceutique", "buttons": [{"id": "btn-tj68rde9", "icon": "none", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-estim", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Réalisations", "breadcrumb": true, "parentLink": "/realisations/", "parentLabel": "Réalisations", "backgroundImage": "/themes/ultra-s/images/pexen/centrale-froid.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-gcmn6gkj", "data": {"html": "<h2>Le site avant travaux</h2>\\n<p>Un site de production pharmaceutique qui fonctionne en continu, avec une chaufferie vapeur, une production de froid process et des réseaux de distribution. Le relevé de PEXEN a porté sur la chaudière vapeur et son brûleur, le groupe de production de froid, les ballons, les pompes et les réseaux de tuyauterie.<br/>[À compléter par Abdou : consommations de référence sur 12 mois : gaz ou vapeur, électricité du froid]</p>\\n<h2>Efficacité énergétique industrielle : ce que PEXEN a installé</h2>\\n<ul><li>[À compléter par Abdou : opération 1, par exemple récupération de chaleur fatale par pompe à chaleur (IND-UT-137)]</li><li>[À compléter par Abdou : opération 2, par exemple calorifugeage des réseaux et matelas isolants (IND-UT-131, IND-UT-121)]</li><li>[À compléter par Abdou : opération 3, par exemple brûleur micro-modulant ou pilotage (IND-UT-105, IND-UT-134)]</li></ul>\\n<h2>Le chantier étape par étape</h2>\\n<ol><li>Relevé sur site : chaufferie vapeur, production de froid, réseaux (réalisé).</li><li>[À compléter par Abdou : étude et dimensionnement : notes de calcul, date]</li><li>[À compléter par Abdou : travaux : période, contraintes de production]</li><li>[À compléter par Abdou : mise en service, contrôle et suivi des consommations]</li></ol>\\n<h2>Avant et après travaux</h2>\\n<h2>Les chiffres du projet</h2>\\n<ul><li>[À compléter par Abdou : économies d'énergie estimées (GWh cumac* ou % sur le poste traité)]</li><li>[À compléter par Abdou : heures de fonctionnement annuelles des équipements traités]</li></ul>\\n<p class=\\"text-sm text-slate-500\\">* Volume d'économies d'énergie estimé selon les fiches d'opérations standardisées mobilisées : le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements. Il ne constitue pas une mesure des consommations réelles.</p>\\n<h2>Un projet ? Parlons-en.</h2>\\n<p>Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.</p>", "image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "ratio": "landscape", "title": "Colorcon : efficacité énergétique industrielle d'un site pharmaceutique", "bullets": ["Récupération de chaleur sur utilités industriell", "Intervention en environnement pharmaceutique san"], "buttons": [], "eyebrow": "COLORCON · BAZAINVILLE (78)", "autoplay": false, "imageAlt": "Colorcon : efficacité énergétique industrielle d'un site pharmaceutique", "highlight": "", "mediaType": "image", "mediaStyle": "logoMask", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-0lc2i8qq", "data": {"limit": 3, "title": "Autres réalisations", "filter": "all", "layout": "grid", "eyebrow": "Réalisations", "headerLink": "/realisations/", "showFilters": false, "headerLinkLabel": "Voir toutes les réalisations"}, "type": "projects", "style": {"background": "surface", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-5ik38dke", "data": {"text": "Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-mearoa10", "icon": "none", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy"}}]	{"slug": "realisations/colorcon-efficacite-energetique-industrielle", "noindex": true, "nofollow": false, "seoTitle": "Efficacité énergétique industrielle chez Colorcon | PEXEN", "schemaType": "Article", "twitterCard": "summary_large_image", "focusKeyphrase": "efficacité énergétique industrielle", "metaDescription": "Efficacité énergétique industrielle sur un site pharmaceutique Colorcon : chaufferie vapeur, production de froid et réseaux calorifugés, relevés et étude PEXEN."}	34	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-11-03 13:23:51.408+01	{"badge": "Industrie pharmaceutique", "cumac": "9,4 GWh cumac", "image": "/themes/ultra-s/images/pexen/centrale-froid.webp", "client": "COLORCON · BAZAINVILLE (78)", "sector": "Industrie", "results": ["Récupération de chaleur sur utilités industrielles & groupes froids process", "Intervention en environnement pharmaceutique sans arrêt de production"], "summary": "Optimisation des utilités d’un site pharmaceutique fonctionnant en continu : récupération de chaleur sur groupes froids process, régulation HP flottante et isolation des points singuliers vapeur/eau surchauffée.", "ceeSheet": "IND-UT-103 · IND-UT-137 · IND-UT-116 · IND-UT-121", "featured": true, "location": "Bazainville", "primeCee": "96 000 €", "solution": "Chaleur fatale industrielle, froid process & matelas thermiques", "department": "78"}
p-mjf6y4zd	/realisations/	Réalisations	published	cms	default	[{"id": "b-0na5jhhf", "data": {"image": "/themes/ultra-s/images/pexen/projets-de-performance-energetique-realises-par-pexen.webp", "intro": "Quatre projets d’efficacité énergétique, quatre configurations : un supermarché qui sort du fioul, une moyenne surface sous contrat de performance énergétique, un magasin de grande hauteur, un site pharmaceutique. Pour chacun : l’enjeu de départ, les solutions retenues, les fiches CEE mobilisées et l’économie d’énergie estimée.", "title": "Nos réalisations", "buttons": [{"id": "btn-ra286tjj", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-r58oaq7x", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Réalisations", "metrics": [{"id": "m-gmzqno2f", "label": "4 configurations", "value": "4 projets"}, {"id": "m-rwkeaid1", "label": "estimés sur l’ensemble", "value": "47,5 GWh cumac*"}, {"id": "m-aac8qbmx", "label": "2 secteurs", "value": "3 régions"}], "imageAlt": "Projets d’efficacité énergétique réalisés par PEXEN", "highlight": "", "breadcrumb": true, "heroVariant": "solution"}, "type": "pageHeader", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "md"}}, {"id": "b-54twurtk", "data": {"html": "<article id=\\"intermarche\\" class=\\"px-ultra-ref\\">\\n      <h2 id=\\"intermarche\\">Intermarché : sortir du fioul et optimiser le froid</h2>\\n      <p class=\\"px-ultra-ref__meta\\">Bourgogne-Franche-Comté · Grande distribution</p>\\n      <p><img src=\\"/themes/ultra-s/images/pexen/pompes-a-chaleur-air-eau-sortie-du-fioul-chez-intermarche.webp\\" alt=\\"Pompe à chaleur air/eau installée par PEXEN chez Intermarché\\" loading=\\"lazy\\" /></p>\\n      <h3>L'enjeu</h3><p>Un supermarché chauffé par deux chaudières fioul vétustes, une production de froid commercial énergivore et un objectif de décarbonation.</p>\\n<h3>Les solutions</h3><ul><li>Pompe à chaleur air/eau en remplacement du fioul.</li><li>Récupération de chaleur sur le groupe froid.</li><li>Déstratification d'air de la surface de vente.</li><li>GTB de classe B.</li><li>Fermeture des meubles frigorifiques et haute pression flottante.</li></ul>\\n<h3>Fiches CEE mobilisées</h3><p>BAT-TH-163 (Coup de pouce) · BAT-TH-139 · BAT-TH-134 · BAT-TH-116 · BAT-TH-142 · BAT-EQ-124</p>\\n      <p class=\\"px-ultra-ref__result\\"><strong>14,8 GWh cumac d’économies d’énergie estimées* · sortie complète du fioul</strong></p>\\n    </article>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-dww47xu1", "data": {"html": "<article id=\\"carrefour-market\\" class=\\"px-ultra-ref\\">\\n      <h2 id=\\"carrefour-market\\">Carrefour Market : froid, chaleur et toiture sous contrat de performance</h2>\\n      <p class=\\"px-ultra-ref__meta\\">Île-de-France · Grande distribution</p>\\n      <p><img src=\\"/themes/ultra-s/images/pexen/recuperation-de-chaleur-sur-la-centrale-froid-de-carrefour-market.webp\\" alt=\\"Centrale de froid commercial chez Carrefour Market, projet d’efficacité énergétique PEXEN\\" loading=\\"lazy\\" /></p>\\n      <h3>L'enjeu</h3><p>Une centrale de froid commercial de sept compresseurs, le premier poste électrique du magasin, et un objectif de réduction garanti par contrat.</p>\\n<h3>Les solutions</h3><ul><li>Récupération de chaleur sur la centrale froid.</li><li>Régulation haute pression flottante.</li><li>Isolation de la toiture-terrasse.</li><li>Fermeture des meubles à température positive et négative.</li></ul>\\n<h3>Fiches CEE mobilisées</h3><p>BAT-TH-139 · BAT-TH-134 · BAT-EN-107 · BAT-EQ-124 · BAT-EQ-125, avec bonification contrat de performance énergétique</p>\\n      <p class=\\"px-ultra-ref__result\\"><strong>30,6 GWh cumac d’économies d’énergie estimées* · objectif contractuel −40 % sur le périmètre traité</strong></p>\\n    </article>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-2fevhcay", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-z9fci52j", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-rvrt7xiv", "data": {"html": "<article id=\\"cedim\\" class=\\"px-ultra-ref\\">\\n      <h2 id=\\"cedim\\">CEDIM : ramener la chaleur au sol</h2>\\n      <p class=\\"px-ultra-ref__meta\\">Centre-Val de Loire · Négoce et entrepôt</p>\\n      <p><img src=\\"/themes/ultra-s/images/pexen/destratificateur-d-air-installe-dans-un-magasin-de-grande-hauteur.webp\\" alt=\\"Déstratificateurs d’air installés par PEXEN chez CEDIM\\" loading=\\"lazy\\" /></p>\\n      <h3>L'enjeu</h3><p>Un magasin de plus de 5 mètres sous plafond, chauffé par aérothermes gaz : l'air chaud stagne sous la toiture, le sol reste froid.</p>\\n<h3>La solution</h3><p>Trois déstratificateurs d'air qui renvoient la chaleur vers la zone occupée.</p>\\n<h3>Fiche CEE mobilisée</h3><p>BAT-TH-142</p>\\n      <p class=\\"px-ultra-ref__result\\"><strong>2,1 GWh cumac d’économies d’énergie estimées*</strong></p>\\n    </article>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-ibnsxlcp", "data": {"html": "<article id=\\"colorcon\\" class=\\"px-ultra-ref\\">\\n      <h2 id=\\"colorcon\\">Colorcon : chaufferie vapeur et froid process</h2>\\n      <p class=\\"px-ultra-ref__meta\\">Île-de-France · Industrie pharmaceutique</p>\\n      <p><img src=\\"/themes/ultra-s/images/pexen/chaufferie-vapeur-d-un-site-industriel-efficacite-energetique-industrielle.webp\\" alt=\\"Chaufferie vapeur du site Colorcon, projet d’efficacité énergétique industrielle\\" loading=\\"lazy\\" /></p>\\n      <h3>L'enjeu</h3><p>Un site de production pharmaceutique dont les utilités tournent en continu : chaufferie vapeur, production de froid, réseaux de distribution.</p>\\n<h3>Les pistes étudiées</h3><p>Récupération de chaleur, pompe à chaleur en rehausse de chaleur fatale, régulation du groupe froid, brûleur micro-modulant, calorifugeage des réseaux.</p>\\n<h3>Fiches CEE étudiées</h3><p>IND-UT-137 · IND-UT-103 · IND-UT-116 · IND-UT-105 · IND-UT-131</p>\\n      \\n    </article>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-6yubmwrq", "data": {"text": "", "title": "Parlons de votre projet", "layout": "centered", "buttons": [{"id": "btn-fianid0m", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-bdt0l3gg", "data": {"html": "<h2>Comment lire nos chiffres</h2><p>Les volumes affichés sont exprimés en kWh cumac, l'unité officielle des certificats d'économies d'énergie. Ils sont calculés hors bonifications, à partir des fiches standardisées mobilisées sur chaque projet. Les économies mesurées sur les factures seront publiées au fil du suivi des consommations.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-qkmf68do", "data": {"html": "<h2>Grande distribution, négoce, industrie</h2><p>Trois des quatre projets concernent la grande distribution et le négoce, où le froid commercial et le chauffage des grands volumes concentrent l'essentiel des consommations. Le quatrième porte sur un site pharmaceutique, dont les utilités fonctionnent en continu. Chaque projet associe au moins deux expertises PEXEN : froid, chaleur, pilotage ou isolation.</p><p><a href=\\"/expertises/\\">Nos expertises</a></p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-njeetzmn", "data": {"text": "", "title": "Demander une étude", "layout": "centered", "buttons": [{"id": "btn-sfzuflsj", "icon": "arrow", "link": "/contact/?demande=etude", "label": "Demander une étude", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-hxlizp3d", "data": {"cards": [{"id": "ck-v2mvo422", "icon": "fa-check", "title": "", "entries": [{"id": "e-8pki03be", "title": "Un relevé sur site avant toute préconisation."}, {"id": "e-rlik2u8f", "title": "Plusieurs actions combinées sur un même site, rarement une seule."}, {"id": "e-9oopmry8", "title": "Des travaux menés sans fermer le magasin ni arrêter la production."}, {"id": "e-pvp84ylh", "title": "Un dossier CEE engagé avant la signature des devis."}]}], "intro": "", "title": "Ce que ces projets ont en commun"}, "type": "checklist", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-3vu3e2q8", "data": {"html": "<h2>Votre site ressemble à l'un de ces projets ?</h2><p>Supermarché équipé d'une centrale froid, bâtiment chauffé au fioul, entrepôt de grande hauteur, site industriel à vapeur : décrivez-nous votre configuration, un ingénieur vous indique sous 48 h ouvrées les actions à étudier en priorité.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-ld4q9rf4", "data": {"html": "<p class=\\"text-xs text-slate-500\\">* Estimation calculée selon les fiches d’opérations standardisées CEE mobilisées (arrêté du 22 décembre 2014 modifié). Le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements ; il ne mesure pas les consommations réelles.</p>", "size": "normal"}, "type": "richText", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-ed3xkji5", "data": {"text": "", "title": "Parlons de votre projet", "layout": "centered", "buttons": [{"id": "btn-jvgsth84", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "light"}, "type": "cta", "style": {"background": "white", "paddingTop": "md", "paddingBottom": "md"}}, {"id": "b-c6ued2ky", "data": {"html": "<h2>Nos projets d'efficacité énergétique en chiffres</h2><p>47,5 GWh cumac d'économies d'énergie estimées sur l'ensemble de ces projets*, trois régions, deux secteurs, huit fiches CEE mobilisées sur les projets engagés.</p>", "size": "normal"}, "type": "richText", "style": {"background": "soft", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-z0dp4n9c", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-elw9lwxk", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-efjgan2j", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "realisations", "noindex": false, "nofollow": false, "seoTitle": "Projets d'efficacité énergétique : 4 références | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "projets d'efficacité énergétique", "metaDescription": "Projets d'efficacité énergétique PEXEN : Intermarché, Carrefour Market, CEDIM, Colorcon. Solutions installées, fiches CEE et économies d'énergie estimées."}	38	2026-10-21 12:54:58.55+02	\N	2026-10-21 12:54:58.55+02	2026-11-03 13:23:51.407+01	\N
