p-ws8phyzv	/realisations/cedim/	Plateforme logistique CEDIM — Déstratification d’air & pilotage GTB	draft	cms	project	[{"id": "b-2tjjk9iv", "data": {"image": "/themes/ultra-s/images/pexen/climatisation-toiture.webp", "intro": "Traitement du gradient thermique vertical sur un bâtiment de négoce et d’entreposage de grande hauteur chauffé par aérothermes gaz, couplé à une GTB communicante.", "title": "Déstratification d’air grands volumes & pilotage GTB classe A", "buttons": [{"id": "btn-1g4svf9x", "icon": "arrow", "link": "/contact/", "label": "Étudier un projet similaire", "variant": "primary"}, {"id": "btn-p577e5ug", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Tertiaire · Centre-Val de Loire (45)", "backLink": "/realisations/", "imageAlt": "Plateforme logistique CEDIM — Déstratification d’air & pilotage GTB", "backLabel": "Toutes les réalisations", "breadcrumb": true, "parentLink": "/realisations/", "parentLabel": "Réalisations"}, "type": "pageHeader", "style": {}}, {"id": "b-8edulpwi", "data": {"items": [{"id": "st-fvb3v59p", "label": "Prime CEE valorisée", "value": "64 000 €"}, {"id": "st-jmz8lj6j", "label": "Économie chauffage", "value": "−26 %"}, {"id": "st-9cdl8jat", "label": "Écart sol / plafond", "value": "< 1,5 °C"}, {"id": "st-j1tzk9oz", "label": "Conformité BACS", "value": "Classe A"}], "style": "cards", "title": "Impact énergétique & financier", "countUp": false, "eyebrow": "Chiffres clés du chantier", "footnote": ""}, "type": "stats", "style": {}}, {"id": "b-krsj8x79", "data": {"html": "<p>Traitement du gradient thermique vertical sur un bâtiment de négoce et d’entreposage de grande hauteur chauffé par aérothermes gaz, couplé à une GTB communicante.</p>", "image": "/themes/ultra-s/images/pexen/climatisation-toiture.webp", "ratio": "landscape", "title": "Déstratification d’air grands volumes & pilotage GTB classe A", "bullets": ["Déstratificateurs haute performance sur hall gra", "Conformité décret BACS & baisse jusqu’à 30 % des"], "buttons": [], "eyebrow": "PLATEFORME LOGISTIQUE CEDIM", "autoplay": false, "imageAlt": "Déstratification d’air grands volumes & pilotage GTB classe A", "highlight": "", "mediaType": "image", "mediaStyle": "logoMask", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-ld6f4syi", "data": {"limit": 3, "title": "Autres réalisations", "filter": "all", "layout": "grid", "eyebrow": "Réalisations", "headerLink": "/realisations/", "showFilters": false, "headerLinkLabel": "Voir toutes les réalisations"}, "type": "projects", "style": {"background": "surface", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-bkskpps8", "data": {"text": "Nos ingénieurs chiffrent gratuitement votre gisement d’économies d’énergie et le montant de votre prime CEE sous 48 h ouvrées.", "title": "Vous avez une installation similaire ?", "layout": "split", "buttons": [{"id": "btn-si9v78qy", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-z0fvpag7", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "variant": "dark"}, "type": "cta", "style": {}}]	{"slug": "realisations/cedim", "noindex": false, "nofollow": false, "seoTitle": "Plateforme logistique CEDIM — Déstratification d’air & pilotage GTB | PEXEN", "schemaType": "Article", "twitterCard": "summary_large_image", "focusKeyphrase": "", "metaDescription": "Traitement du gradient thermique vertical sur un bâtiment de négoce et d’entreposage de grande hauteur chauffé par aérothermes gaz, couplé à une GTB communicante."}	42	2026-10-21 12:54:58.548+02	\N	2026-10-21 12:54:58.548+02	2026-11-03 13:23:51.408+01	{"badge": "Décret BACS & Logistique", "cumac": "2,1 GWh cumac", "image": "/themes/ultra-s/images/pexen/climatisation-toiture.webp", "client": "PLATEFORME LOGISTIQUE CEDIM", "sector": "Tertiaire", "results": ["Déstratificateurs haute performance sur hall grande hauteur (> 5 m à 12 m)", "Conformité décret BACS & baisse jusqu’à 30 % des consommations de chauffage"], "summary": "Traitement du gradient thermique vertical sur un bâtiment de négoce et d’entreposage de grande hauteur chauffé par aérothermes gaz, couplé à une GTB communicante.", "ceeSheet": "BAT-TH-142 · BAT-TH-116", "featured": true, "location": "Centre-Val de Loire", "primeCee": "64 000 €", "solution": "Déstratification d’air grands volumes & pilotage GTB classe A", "department": "45"}
page-3r6inn5v	/expertises/recuperation-de-chaleur/	Récupération de chaleur	draft	cms	default	[{"id": "b-sd1oflt9", "data": {"image": "/images/centrale-froid.webp", "intro": "Chaque groupe froid, chaque compresseur d'air, chaque process chaud rejette de la chaleur dans l'atmosphère. La récupération de chaleur capte cette énergie et la redirige vers le chauffage des locaux, l'eau chaude sanitaire ou le préchauffage d'un process. Elle réduit la consommation de la chaudière sans ajouter de combustible. Une énergie déjà payée, enfin utilisée.", "title": "Récupération de chaleur : chauffer avec l'énergie que vous rejetez", "buttons": [{"id": "btn-up28h8ht", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-estim", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "PEXEN", "imageAlt": "Récupération de chaleur sur groupe froid installée par PEXEN", "breadcrumb": true, "parentLink": "", "heroVariant": "expertise", "parentLabel": ""}, "type": "pageHeader", "style": {"background": "surface", "paddingBottom": "md"}}, {"id": "b-75pzf28l", "data": {"items": [{"id": "c-k4v2vj39", "tags": [], "text": "Un échangeur placé en sortie de compresseur alimente un réseau d'eau chaude ou une batterie de traitement d'air. Durée de vie conventionnelle : 14 ans. Fiches CEE : BAT-TH-139 (tertiaire) · IND-UT-117 (industrie, sous réserve de maintien de la fiche).", "title": "Sur groupe de production de froid"}, {"id": "c-eg5e5540", "tags": [], "text": "La chaleur du circuit d'huile ou de l'air de refroidissement préchauffe l'eau ou chauffe un atelier voisin. Fiche CEE : IND-UT-103.", "title": "Sur compresseur d'air"}, {"id": "c-i4943kl4", "tags": [], "text": "Quand la chaleur disponible est trop basse en température (25 à 40 °C), une pompe à chaleur la relève au niveau requis. Fiche CEE : IND-UT-137.", "title": "Pompe à chaleur en rehausse de chaleur fatale"}, {"id": "c-ssxv5q53", "tags": [], "text": "Un échangeur sur l'évacuation des douches préchauffe l'eau froide entrante. Adapté aux établissements de santé, aux salles de sport et aux hôtels. Fiche CEE : BAT-TH-154.", "title": "Récupération instantanée sur eaux grises"}], "style": "card", "title": "Nos solutions de valorisation de la chaleur", "columns": 2}, "type": "cards", "style": {}}, {"id": "b-ocwzqr0x", "data": {"html": "<h2>Les conditions d'un projet rentable</h2><p>Le projet tient si trois conditions sont réunies : des besoins de chaleur simultanés aux rejets, une distance courte entre source et usage, une régulation du froid qui reste prioritaire. Notre étude croise les courbes de rejet et de besoin heure par heure avant de dimensionner l'échangeur et le stockage.</p><p class=\\"text-xs text-slate-500\\">* Estimation calculée selon les fiches d'opérations standardisées CEE mobilisées (arrêté du 22 décembre 2014 modifié). Le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements ; il ne mesure pas les consommations réelles.</p>", "size": "normal"}, "type": "richText", "style": {}}, {"id": "b-d953bqpa", "data": {"items": [{"id": "q-x8uglw26", "answer": "Cela dépend de la puissance du groupe froid, de son temps de fonctionnement et de vos besoins. Dans un supermarché, la chaleur rejetée par la centrale froid dépasse souvent le besoin de chauffage du magasin hors grands froids.", "question": "Quelle part de mon chauffage la chaleur récupérée peut-elle couvrir ?"}, {"id": "q-q4at9al5", "answer": "Non. L'échangeur s'installe en amont du générateur existant, qui assure l'appoint.", "question": "Mon chauffage actuel doit-il être remplacé ?"}, {"id": "q-pvvmjel6", "answer": "Sa suppression est envisagée par le ministère. Nous vérifions la fiche en vigueur à la date d'engagement de chaque opération.", "question": "La fiche IND-UT-117 est-elle toujours valable ?"}], "title": "Questions fréquentes sur la récupération de chaleur", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {}}, {"id": "b-agfgauv6", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-x16fqctn", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-y63tn2hx", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "image", "backgroundImage": "/images/audit-batiment.webp"}, "type": "cta", "style": {"background": "navy"}}]	{"slug": "expertises/recuperation-de-chaleur", "noindex": true, "nofollow": false, "seoTitle": "Récupération de chaleur sur groupe froid et process | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "récupération de chaleur", "metaDescription": "Récupération de chaleur sur groupe froid, compresseur d'air et chaleur fatale industrielle : chauffez vos locaux et votre eau avec l'énergie que vous rejetez."}	8	2026-10-12 09:36:00.995+02	\N	2026-10-12 09:36:00.995+02	2026-10-30 08:47:32.777+01	\N
page-x9bcm668	/expertises/isolation-technique/	Isolation technique	draft	cms	default	[{"id": "b-7gyl6zd1", "data": {"image": "/images/centrale-froid.webp", "intro": "Une canalisation d'eau chaude ou de vapeur non isolée, une vanne nue, une toiture-terrasse sans isolant : la chaleur produite se perd avant d'atteindre son usage. L'isolation technique traite ces pertes en priorité, avec des temps de retour parmi les plus courts des travaux d'économies d'énergie.", "title": "Isolation technique : limiter les pertes de vos réseaux et de vos toitures", "buttons": [{"id": "btn-eeum9mb5", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-estim", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "PEXEN", "imageAlt": "Isolation technique d'un réseau de chauffage par PEXEN", "breadcrumb": true, "parentLink": "", "heroVariant": "expertise", "parentLabel": ""}, "type": "pageHeader", "style": {"background": "surface", "paddingBottom": "md"}}, {"id": "b-5or75ttl", "data": {"items": [{"id": "c-i5qn5kr4", "tags": [], "text": "Isolation des tuyauteries, ballons et parois planes ou cylindriques. Fiche CEE : IND-UT-131.", "title": "Calorifugeage des réseaux et des équipements"}, {"id": "c-ngw07o5q", "tags": [], "text": "Housses taillées pour chaque pièce, démontables sans outil. Fiche CEE : IND-UT-121.", "title": "Matelas isolants sur points singuliers"}, {"id": "c-v5k9tdtm", "tags": [], "text": "Isolant posé sur l'étanchéité ou sous une nouvelle étanchéité. Durée de vie conventionnelle : 30 ans. Fiche CEE : BAT-EN-107.", "title": "Isolation des toitures-terrasses"}], "style": "card", "title": "Nos solutions d'isolation technique", "columns": 3}, "type": "cards", "style": {}}, {"id": "b-w169exmn", "data": {"html": "<p>Nous relevons chaque tronçon et chaque point singulier : diamètre, longueur, température du fluide, ambiance. Une thermographie infrarouge localise les pertes invisibles. Le chiffrage classe les actions par temps de retour, CEE déduits.</p><p class=\\"text-xs text-slate-500\\">* Estimation calculée selon les fiches d'opérations standardisées CEE mobilisées (arrêté du 22 décembre 2014 modifié). Le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements ; il ne mesure pas les consommations réelles.</p>", "size": "normal"}, "type": "richText", "style": {}}, {"id": "b-ansh8rwd", "data": {"items": [{"id": "q-e4pbshm4", "answer": "Non dans la plupart des cas : les isolants et matelas se posent sur des réseaux en service.", "question": "Faut-il arrêter l'installation pour la calorifuger ?"}, {"id": "q-h6ae622x", "answer": "Oui, en industrie avec les fiches IND-UT-131 et IND-UT-121, en tertiaire pour la toiture-terrasse avec BAT-EN-107.", "question": "Le calorifugeage est-il financé par les CEE ?"}, {"id": "q-1npe38er", "answer": "Oui, avec un isolant à pare-vapeur continu : une discontinuité suffit à créer de la condensation, puis de la corrosion sous l'isolant.", "question": "Isolez-vous aussi les réseaux d'eau glacée ?"}], "title": "Questions fréquentes sur l'isolation technique", "layout": "stacked", "eyebrow": "FAQ", "showContactCard": false}, "type": "faq", "style": {}}, {"id": "b-kqbddfce", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-sguxg04p", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-34di087o", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "image", "backgroundImage": "/images/audit-batiment.webp"}, "type": "cta", "style": {"background": "navy"}}]	{"slug": "expertises/isolation-technique", "noindex": true, "nofollow": false, "seoTitle": "Isolation technique : réseaux et toitures | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "isolation technique", "metaDescription": "Isolation technique des réseaux et des bâtiments : calorifugeage industriel, matelas isolants, toitures-terrasses."}	9	2026-10-12 09:36:00.995+02	\N	2026-10-12 09:36:00.995+02	2026-10-30 08:47:32.777+01	\N
p-49n439wi	/realisations/cedim-destratification/	Réalisation : CEDIM	draft	cms	project	[{"id": "b-81h8n4hd", "data": {"image": "/themes/ultra-s/images/pexen/climatisation-toiture.webp", "intro": "Centre-Val de Loire · Négoce et entrepôt", "title": "CEDIM : déstratification d'un magasin de grande hauteur", "buttons": [{"id": "btn-72q9sjtw", "icon": "none", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-estim", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "Réalisations", "breadcrumb": true, "parentLink": "/realisations/", "parentLabel": "Réalisations", "backgroundImage": "/themes/ultra-s/images/pexen/climatisation-toiture.webp"}, "type": "pageHeader", "style": {}}, {"id": "b-nmn6ouht", "data": {"items": [{"id": "k-wukwl7f8", "label": "de hauteur sous toiture traitée", "value": "9", "prefix": "", "suffix": "m"}, {"id": "k-xsgaqz2v", "label": "de magasin chauffé", "value": "1213", "prefix": "", "suffix": "m²"}, {"id": "k-8egtjv7r", "label": "déstratificateurs d'air asservis à la température", "value": "3", "prefix": "", "suffix": ""}, {"id": "k-yn2vqnmw", "label": "d'économies d'énergie estimées", "value": "2,1", "prefix": "", "suffix": "GWh cumac*"}], "style": "strip", "title": "Chiffres clés", "countUp": true, "footnote": ""}, "type": "stats", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-iba3k7ge", "data": {"html": "<h2>Le site avant travaux</h2>\\n<p>Un magasin de grande hauteur chauffé par cinq aérothermes gaz : l'air chaud s'accumule sous la toiture, le sol reste froid et les aérothermes compensent.</p>\\n<h2>Déstratification : ce que PEXEN a installé</h2>\\n<p>Des déstratificateurs d'air installés à 9 m, sous la toiture, asservis à une sonde de température haute, ramènent la chaleur déjà produite vers la zone occupée. La chaleur déjà produite est mieux répartie, sans augmenter la puissance de chauffage.</p>\\n<h2>Le chantier étape par étape</h2>\\n<ol><li>Étude : relevé des aérothermes gaz et de la hauteur sous plafond.</li><li>Dimensionnement : note de calcul de la déstratification, maillage des appareils.</li><li>Installation en site ouvert et réglage des seuils de déclenchement.</li><li>Contrôle de conformité et suivi du fonctionnement des aérothermes.</li></ol>\\n<h2>Avant et après travaux</h2>\\n<h2>Les chiffres du projet</h2>\\n<ul><li>Température plus homogène entre le sol et la toiture.</li><li>Temps de fonctionnement des aérothermes réduit.</li><li>Meilleur confort des équipes et des clients.</li></ul>\\n<p class=\\"text-sm text-slate-500\\">* Volume d'économies d'énergie estimé selon les fiches d'opérations standardisées mobilisées : le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements. Il ne constitue pas une mesure des consommations réelles.</p>\\n<h2>Un projet ? Parlons-en.</h2>\\n<p>Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.</p>", "image": "/themes/ultra-s/images/pexen/climatisation-toiture.webp", "ratio": "landscape", "title": "CEDIM : déstratification d'un magasin de grande hauteur", "bullets": ["1 213 m² · 2,1 GWh cumac*"], "buttons": [], "eyebrow": "CEDIM", "autoplay": false, "imageAlt": "CEDIM : déstratification d'un magasin de grande hauteur", "highlight": "", "mediaType": "image", "mediaStyle": "logoMask", "videoSource": "file", "mediaPosition": "right"}, "type": "textMedia", "style": {"background": "white", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-nnz94vhd", "data": {"limit": 3, "title": "Autres réalisations", "filter": "all", "layout": "grid", "eyebrow": "Réalisations", "headerLink": "/realisations/", "showFilters": false, "headerLinkLabel": "Voir toutes les réalisations"}, "type": "projects", "style": {"background": "surface", "paddingTop": "lg", "paddingBottom": "lg"}}, {"id": "b-60uacti9", "data": {"text": "Prise de contact sous 48 h ouvrées par un ingénieur PEXEN, pour qualifier votre besoin et définir les prochaines étapes.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-dn6ll427", "icon": "none", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy"}}]	{"slug": "realisations/cedim-destratification", "noindex": false, "nofollow": false, "seoTitle": "Déstratification chez CEDIM : grande hauteur | PEXEN", "schemaType": "Article", "twitterCard": "summary_large_image", "focusKeyphrase": "déstratification", "metaDescription": "Déstratification chez CEDIM : déstratificateurs installés à 9 m de hauteur dans un magasin de 1 213 m² chauffé au gaz, chaleur ramenée vers la zone occupée."}	2	2026-10-21 12:43:13.023+02	\N	2026-10-21 12:43:13.023+02	2026-11-03 13:23:51.408+01	{"badge": "", "cumac": "2,1 GWh cumac", "image": "/themes/ultra-s/images/pexen/realisation-cedim-batiment.webp", "client": "CEDIM", "sector": "Négoce et entrepôt", "results": ["1 213 m² · 2,1 GWh cumac*"], "summary": "Centre-Val de Loire · Négoce et entrepôt", "ceeSheet": "", "featured": true, "location": "Centre-Val de Loire", "primeCee": "", "solution": "9 m de hauteur traitée par déstratification", "sortOrder": 2, "department": "45"}
