page-vqhuknex	/expertises/renovation-globale-tertiaire/	Rénovation globale tertiaire	draft	cms	default	[{"id": "b-91hckywa", "data": {"intro": "La rénovation globale tertiaire traite ensemble l'enveloppe, la production de chaleur et de froid, la ventilation et le pilotage d'un bâtiment. Une fiche CEE dédiée financera ces bouquets de travaux dès sa parution. Elle complète les fiches par équipement pour les projets qui visent les objectifs du décret tertiaire.", "title": "Rénovation globale tertiaire : un bouquet de travaux, un seul dossier", "buttons": [{"id": "btn-4rrz02k4", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-estim", "icon": "none", "link": "/simulateur-prime-cee/", "label": "Estimer le financement", "variant": "secondary"}], "eyebrow": "PEXEN", "breadcrumb": true, "parentLink": "", "heroVariant": "expertise", "parentLabel": ""}, "type": "pageHeader", "style": {"background": "surface", "paddingBottom": "md"}}, {"id": "b-cp5padj9", "data": {"html": "<p>Page en préparation : elle sera publiée quand l'arrêté créant la fiche CEE sera paru au Journal officiel. La fiche BAR-TH-177 finance déjà la rénovation globale des bâtiments résidentiels collectifs.</p>", "size": "normal"}, "type": "richText", "style": {}}, {"id": "b-c9d60amo", "data": {"text": "Un ingénieur PEXEN étudie votre site, évalue le gisement et vous répond sous 48 h ouvrées.", "title": "Un projet ? Parlons-en.", "layout": "centered", "buttons": [{"id": "btn-5yckk38f", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}, {"id": "btn-8jn9yep4", "icon": "phone", "link": "tel:+33141935280", "label": "01 41 93 52 80", "variant": "secondary"}], "variant": "image", "backgroundImage": "/images/audit-batiment.webp"}, "type": "cta", "style": {"background": "navy"}}]	{"slug": "expertises/renovation-globale-tertiaire", "noindex": true, "nofollow": false, "seoTitle": "Rénovation globale tertiaire et CEE | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "rénovation globale tertiaire", "metaDescription": "Rénovation globale tertiaire : bouquet de travaux, audit et financement CEE par la future fiche dédiée."}	15	2026-10-18 13:23:13.999+02	\N	2026-10-18 13:23:13.999+02	2026-10-19 11:08:13.888+02	\N
