ut": "centered", "buttons": [{"id": "btn-w6gmqlfh", "icon": "arrow", "link": "/contact/", "label": "Parler de votre projet", "variant": "primary"}], "variant": "dark"}, "type": "cta", "style": {"background": "navy", "paddingTop": "lg", "paddingBottom": "lg"}}]	{"slug": "partenaires", "noindex": false, "nofollow": false, "seoTitle": "Partenaire installateur des délégataires | PEXEN", "schemaType": "WebPage", "twitterCard": "summary_large_image", "focusKeyphrase": "partenaire installateur", "metaDescription": "Partenaire installateur et bureau d'ingénierie pour délégataires, mandataires, fabricants et bureaux d'études : opérations conformes et contrôlées."}	33	2026-10-21 12:43:13.022+02	\N	2026-10-21 12:43:13.022+02	2026-11-03 13:23:51.408+01	\N
