p-1d7822hy	/simulateur-cee/	Simulateur CEE	draft	cms	default	[{"id": "b-x1eoe9m7", "data": {"intro": "Estimation indicative selon les fiches d’opérations standardisées mobilisées.", "title": "Estimez le financement de votre projet", "buttons": [], "eyebrow": "PEXEN", "breadcrumb": true, "parentLink": "", "parentLabel": ""}, "type": "pageHeader", "style": {}}, {"id": "b-bi5ilmwz", "data": {"align": "left", "intro": "Type de site, travaux envisagés, puissance : une première estimation du financement mobilisable.", "title": "Estimez le financement de votre projet", "formId": "contact-main", "eyebrow": "Financement", "howText": "Chaque action correspond à une opération standardisée qui fixe un volume d’économies selon le secteur, la zone climatique et la puissance installée. Ce volume est valorisé au prix du marché ; des bonifications s’appliquent pour la sortie des énergies fossiles ou un contrat de performance énergétique.", "regions": [{"id": "idf", "label": "Île-de-France", "factor": 1.05}, {"id": "hdf", "label": "Hauts-de-France", "factor": 1.08}, {"id": "ge", "label": "Grand Est", "factor": 1.08}, {"id": "nor", "label": "Normandie", "factor": 1.05}, {"id": "bre", "label": "Bretagne", "factor": 1}, {"id": "pdl", "label": "Pays de la Loire", "factor": 1}, {"id": "cvl", "label": "Centre-Val de Loire", "factor": 1.02}, {"id": "bfc", "label": "Bourgogne-Franche-Comté", "factor": 1.06}, {"id": "naq", "label": "Nouvelle-Aquitaine", "factor": 0.95}, {"id": "occ", "label": "Occitanie", "factor": 0.9}, {"id": "ara", "label": "Auvergne-Rhône-Alpes", "factor": 1.04}, {"id": "pac", "label": "Provence-Alpes-Côte d’Azur", "factor": 0.88}, {"id": "cor", "label": "Corse", "factor": 0.85}], "variant": "tool", "ctaLabel": "Envoyer ma demande", "energies": [{"id": "fioul", "label": "Fioul", "factor": 1.25}, {"id": "gaz", "label": "Gaz", "factor": 1.12}, {"id": "electricite", "label": "Électricité", "factor": 1}, {"id": "reseau", "label": "Réseau de chaleur", "factor": 0.95}], "howTit