lisations/carrefour-market-recuperation-de-chaleur/", "label": "de chaleur récupérée sur le froid commercial · Carrefour Market", "value": "535", "suffix": " kW"}, {"id": "k-u11pxqek", "link": "/realisations/intermarche-sortie-du-fioul/", "label": "chauffés et sortis du fioul · Intermarché", "value": "1650", "suffix": " m²"}, {"id": "k-k8t6f9c5", "link": "/realisations/", "label": "d’économies d’énergie estimées sur 3 chantiers", "value": "47.5", "suffix": " GWh cumac*"}, {"id": "k-nqudxtj3", "link": "/contrat-de-performance-energetique/", "label": "d’économie d’énergie visée sur 10 ans par contrat de performance", "value": "40", "suffix": " %*"}], "style": "strip", "title": "Preuves terrain", "countUp": true, "eyebrow": "Ils nous confient leurs sites", "footnote": "* Volume d’économies d’énergie estimé selon les fiches d’opérations standardisées mobilisées : le kWh cumac cumule et actualise les économies sur la durée de vie conventionnelle des équipements. Il ne constitue pas une mesure des consommations réelles.\\n* Objectif contractuel de réduction des consommations, sur le périmètre et la durée du contrat de performance énergétique (10 ans), à conditions d’exploitation comparables.", "partners": [{"logo": "/themes/ultra-s/images/pexen/partners/intermarche.webp", "name": "Intermarché"}, {"logo": "/themes/ultra-s/images/pexen/partners/carrefour-market.webp", "name": "Carrefour Market"}, {"logo": "/themes/ultra-s/images/pexen/partners/cedim.webp", "name": "CEDIM"}, {"logo": "/themes/ultra-s/images/pexen/partners/colorcon.webp", "name": "Colorcon"}], "qualifications": [{"alt": "Qualification RGE QualiPAC de PEXEN", "logo": "/themes/ultra-s/images/pexen/quali/qualipac.webp", "label": "RGE QualiPAC"}, {"alt": "Qualification RGE Qualisol de PEXEN", "logo": "/themes/ultra-s/images/pexen/quali/qualisol.webp", "label": "RGE Qualisol"}, {"alt": "Qualifications OPQIBI de PEXEN", "logo": "/themes/ultra-s/images/pexen/quali/opqibi.webp", "label": "OPQIBI", "caption": "Partena